fn accepted_claim_ledger(ledger: Option<&CtxAnswerLedger>) -> Vec<SettlementClaim> {
    let Some(ledger) = ledger else {
        return Vec::new();
    };
    let mut claims = Vec::with_capacity(ledger.ids.len() + 1);
    claims.push(SettlementClaim {
        field_or_slot: "runtime.now".to_owned(),
        claimed: json!(ledger.now),
        authoritative: json!(ledger.now),
        disposition: SettlementClaimDisposition::Accepted,
        skew_ms: None,
    });
    claims.extend(
        ledger
            .ids
            .iter()
            .enumerate()
            .map(|(index, id)| SettlementClaim {
                field_or_slot: format!("runtime.id[{index}]"),
                claimed: Value::String(id.clone()),
                authoritative: Value::String(id.clone()),
                disposition: SettlementClaimDisposition::Accepted,
                skew_ms: None,
            }),
    );
    claims
}

fn rederived_claim_ledger(
    settlement: &MutationSettlement,
    ledger: Option<&CtxAnswerLedger>,
    authoritative_mints: &[SettlementMintObservation],
    time_observation: Option<&SettlementTimeObservation>,
) -> Vec<SettlementClaim> {
    let Some(recorded) = settlement.claims.as_ref() else {
        return Vec::new();
    };
    let mut claims = Vec::with_capacity(recorded.mints.len() + usize::from(recorded.now.is_some()));
    if let Some(claimed) = recorded.now {
        let bounded = time_observation.filter(|observation| observation.claimed == claimed);
        claims.push(SettlementClaim {
            field_or_slot: bounded.map_or_else(
                || "runtime.now".to_owned(),
                |observation| observation.field.clone(),
            ),
            claimed: json!(claimed),
            authoritative: bounded.map_or_else(
                || ledger.map_or(Value::Null, |ledger| json!(ledger.now)),
                |observation| {
                    json!(if observation.accepted {
                        observation.claimed
                    } else {
                        observation.authoritative_sample
                    })
                },
            ),
            disposition: if bounded.is_some_and(|observation| observation.accepted) {
                SettlementClaimDisposition::AcceptedBoundedSkew
            } else {
                SettlementClaimDisposition::ReDerived
            },
            skew_ms: bounded.map(|observation| observation.skew_ms),
        });
    }
    let authoritative = authoritative_mints_by_key(authoritative_mints);
    let claim_counts = recorded
        .mints
        .iter()
        .fold(BTreeMap::new(), |mut counts, mint| {
        *counts
            .entry((mint.site.clone(), mint.occurrence))
            .or_insert(0_usize) += 1;
        counts
    });
    claims.extend(recorded.mints.iter().map(|mint| {
        SettlementClaim {
        field_or_slot: format!("{}[{}]", mint.site, mint.occurrence),
        claimed: Value::String(mint.claimed.clone()),
        authoritative: exact_authoritative_mint(mint, &claim_counts, &authoritative)
            .map_or(Value::Null, |id| Value::String(id.to_owned())),
        disposition: SettlementClaimDisposition::ReDerived,
        skew_ms: None,
        }
    }));
    claims
}

fn authoritative_mints_by_key(
    observations: &[SettlementMintObservation],
) -> BTreeMap<(String, u32), Vec<String>> {
    observations
        .iter()
        .fold(BTreeMap::new(), |mut by_key, mint| {
        by_key
            .entry((mint.site.clone(), mint.occurrence))
            .or_insert_with(Vec::new)
            .push(mint.id.clone());
        by_key
    })
}

fn exact_authoritative_mint<'a>(
    claim: &crate::manifest::SettlementMintClaim,
    claim_counts: &BTreeMap<(String, u32), usize>,
    authoritative: &'a BTreeMap<(String, u32), Vec<String>>,
) -> Option<&'a str> {
    if claim.site.is_empty()
        || claim_counts.get(&(claim.site.clone(), claim.occurrence)) != Some(&1)
    {
        return None;
    }
    let candidates = authoritative.get(&(claim.site.clone(), claim.occurrence))?;
    (candidates.len() == 1).then(|| candidates[0].as_str())
}

fn settlement_id_map(
    settlement: &MutationSettlement,
    authoritative_mints: &[SettlementMintObservation],
) -> Option<Vec<SettlementIdMapEntry>> {
    if settlement.lane != SettlementLane::ReDerive {
        return None;
    }
    // Exact key equality is the complete construction rule. Equal total
    // counts, neighboring ctx-ledger positions, or a plausible table prefix
    // cannot rescue a missing key. Duplicate keys are ambiguous and therefore
    // become unmapped too.
    // @ref LLP 0133#divergence-on-settle — no cross-site or count-based id
    //   pairing; within-site occurrence is the explicitly retained OQ2 residue.
    let recorded = settlement.claims.as_ref();
    let claim_counts = recorded.into_iter().flat_map(|claims| &claims.mints).fold(
        BTreeMap::new(),
        |mut counts, mint| {
            *counts
                .entry((mint.site.clone(), mint.occurrence))
                .or_insert(0_usize) += 1;
            counts
        },
    );
    let authoritative = authoritative_mints_by_key(authoritative_mints);
    Some(
        recorded
            .into_iter()
            .flat_map(|claims| &claims.mints)
            .map(|mint| {
                let authoritative = exact_authoritative_mint(mint, &claim_counts, &authoritative)
                    .map(str::to_owned);
                SettlementIdMapEntry {
                    speculative: mint.claimed.clone(),
                    disposition: if authoritative.is_some() {
                        SettlementIdMapDisposition::Mapped
                    } else {
                        SettlementIdMapDisposition::Unmapped
                    },
                    authoritative,
                    site: mint.site.clone(),
                    occurrence: mint.occurrence,
                }
            })
            .collect(),
    )
}

fn settlement_claim_ledger(
    settlement: &MutationSettlement,
    ledger: Option<&CtxAnswerLedger>,
    authoritative_mints: &[SettlementMintObservation],
    time_observation: Option<&SettlementTimeObservation>,
) -> Vec<SettlementClaim> {
    match settlement.lane {
        SettlementLane::ReplayAccept => accepted_claim_ledger(ledger),
        SettlementLane::ReDerive => {
            rederived_claim_ledger(settlement, ledger, authoritative_mints, time_observation)
        }
    }
}

fn admitted_settlement_time_policy(
    function: &FunctionDefinition,
    settlement: &MutationSettlement,
) -> Option<SettlementTimePolicy> {
    if settlement.lane != SettlementLane::ReDerive {
        return None;
    }
    let declared = function.bounded_skew.as_ref()?;
    // The request copy freezes capture-time identity, but cannot widen the
    // artifact-owned declaration. Only exact equality activates the opt-in;
    // every other lane-L shape stays on authoritative re-derivation.
    // @ref LLP 0133#the-bounded-skew-opt-in — bounded acceptance is
    //   declaration authority, structurally admitted at artifact load.
    if settlement.bounded_skew.as_ref() != Some(declared) {
        return None;
    }
    let claimed = settlement.claims.as_ref()?.now?;
    Some(SettlementTimePolicy {
        field: declared.field.clone(),
        claimed,
        max_skew_ms: declared.max_skew_ms,
    })
}

