    pub fn acknowledge_client_mutations(
        &mut self,
        auth: &AuthInput,
        ids: &[String],
    ) -> SnapbackResult<u64> {
        let current = self
            .db
            .acknowledge_client_mutations(&auth_fingerprint(auth), ids)?;
        let legacy = self
            .db
            .acknowledge_client_mutations(&legacy_auth_fingerprint(auth), ids)?;
        current.checked_add(legacy).ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_CLIENT_MUTATION_RETENTION_STATE_INVALID",
                "storage",
                "acknowledged settlement count overflowed across auth aliases",
            )
        })
    }

    pub(crate) fn acknowledge_client_mutations_with_authority(
        &mut self,
        authority: &PreparedAuthority,
        ids: &[String],
    ) -> SnapbackResult<u64> {
        authority.validate_admission("client mutation acknowledgement")?;
        self.persist_and_validate_prepared_service_authority(authority)?;
        let auth = authority.canonical_auth_input();
        let incarnation = self.db.ensure_authorization_stream_incarnation()?;
        let descriptor = descriptor_for_authority(authority, incarnation.as_str())?;
        let _effect = authority.effect_guard("client mutation acknowledgement transaction")?;
        let current = self.db.acknowledge_client_mutations_for_authority(
            &auth_fingerprint(&auth),
            &descriptor.authority_instance_id,
            ids,
        )?;
        let legacy = self.db.acknowledge_client_mutations_for_authority(
            &legacy_auth_fingerprint(&auth),
            &descriptor.authority_instance_id,
            ids,
        )?;
        current.checked_add(legacy).ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_CLIENT_MUTATION_RETENTION_STATE_INVALID",
                "storage",
                "acknowledged settlement count overflowed across auth aliases",
            )
        })
    }

    pub(crate) fn descriptor_for_prepared_authority(
        &mut self,
        authority: &PreparedAuthority,
    ) -> SnapbackResult<AuthorityDescriptor> {
        authority.validate_admission("authority descriptor publication")?;
        self.persist_and_validate_prepared_service_authority(authority)?;
        let incarnation = self.db.ensure_authorization_stream_incarnation()?;
        descriptor_for_authority(authority, incarnation.as_str())
    }

    pub(crate) fn issue_client_operation_identity_range(
        &mut self,
        authority: &PreparedAuthority,
        client_audience_id: &str,
        authority_descriptor: Option<&AuthorityDescriptor>,
        previous: Option<&crate::commit_envelope::ClientIdentityRangeV1>,
    ) -> SnapbackResult<crate::commit_envelope::ClientIdentityRangeV1> {
        authority.validate_admission("operation identity range issuance")?;
        self.persist_and_validate_prepared_service_authority(authority)?;
        let incarnation = self.db.ensure_authorization_stream_incarnation()?;
        let expected = descriptor_for_authority(authority, incarnation.as_str())?;
        if authority.active_mode() == AuthMode::Sessions || authority_descriptor.is_some() {
            require_current_descriptor(authority_descriptor, &expected)?;
        }
        if !crate::manifest::replay_opaque_id_is_valid(client_audience_id) {
            return Err(SnapbackError::error(
                "SNAPBACK_OPERATION_RANGE_AUDIENCE_INVALID",
                "protocol",
                "clientAudienceId must use the bounded opaque replay-id alphabet",
            ));
        }
        use sha2::Digest as _;
        let mut digest = sha2::Sha256::new();
        digest.update(b"snapback:client-range-audience:v1\n");
        digest.update(expected.authority_instance_id.as_bytes());
        digest.update(b"\n");
        digest.update(client_audience_id.as_bytes());
        let audience = format!("sha256:{:x}", digest.finalize());
        let _effect = authority.effect_guard("operation identity range issuance transaction")?;
        self.db.issue_client_operation_identity_range(
            &audience,
            &expected.authority_instance_id,
            previous,
            now_millis(),
        )
    }

    /// Evaluate explanation authorization from the live prepared authority;
    /// callers cannot submit the `current_policy_provable` decision.
    pub(crate) fn explain_operation_with_authority(
        &mut self,
        authority: &PreparedAuthority,
        authority_descriptor: Option<&AuthorityDescriptor>,
        identity: &crate::commit_envelope::OperationIdentityV1,
    ) -> SnapbackResult<Option<crate::commit_envelope::OperationExplanationV1>> {
        authority.validate_admission("operation explanation")?;
        self.persist_and_validate_prepared_service_authority(authority)?;
        let incarnation = self.db.ensure_authorization_stream_incarnation()?;
        let expected = descriptor_for_authority(authority, incarnation.as_str())?;
        if authority.active_mode() == AuthMode::Sessions || authority_descriptor.is_some() {
            require_current_descriptor(authority_descriptor, &expected)?;
        }
        let current = crate::operation_ledger::CurrentExplanationAuthorityV1 {
            audience: identity.bound_facts.audience.clone(),
            principal_fingerprint: auth_fingerprint(&authority.canonical_auth_input()),
            authority_instance_id: expected.authority_instance_id,
            // Exact current principal/incarnation matching is necessary but
            // not sufficient to re-evaluate every row/non-row fact policy.
            // Until the per-fact evaluator is wired, public transport stays
            // fail-closed with an explicit authorization-unprovable result.
            current_policy_provable: false,
            allow_non_row_facts: false,
            administrative: false,
        };
        self.db.explain_operation(identity, &current)
    }

    pub(crate) fn explain_operation_as_admin(
        &self,
        identity: &crate::commit_envelope::OperationIdentityV1,
    ) -> SnapbackResult<Option<crate::commit_envelope::OperationExplanationV1>> {
        let current = crate::operation_ledger::CurrentExplanationAuthorityV1 {
            audience: identity.bound_facts.audience.clone(),
            principal_fingerprint: String::new(),
            authority_instance_id: String::new(),
            current_policy_provable: true,
            allow_non_row_facts: true,
            administrative: true,
        };
        self.db.explain_operation(identity, &current)
    }

    pub(crate) fn acknowledge_client_mutations_with_authority_descriptor(
        &mut self,
        authority: &PreparedAuthority,
        authority_descriptor: Option<&AuthorityDescriptor>,
        ids: &[String],
    ) -> SnapbackResult<u64> {
        if let Some(supplied) = authority_descriptor {
            authority.validate_admission("client mutation acknowledgement")?;
            self.persist_and_validate_prepared_service_authority(authority)?;
            let incarnation = self.db.ensure_authorization_stream_incarnation()?;
            let expected = descriptor_for_authority(authority, incarnation.as_str())?;
            require_current_descriptor(Some(supplied), &expected)?;
        }
        self.acknowledge_client_mutations_with_authority(authority, ids)
    }

    /// Administrative recovery for settlements whose original client can no
    /// longer deliver an acknowledgement. The HTTP boundary supplies an
    /// `AuthInput`, never a caller-chosen raw fingerprint, so targeted purge
    /// uses exactly the same canonical identity as commit and ACK.
    pub fn purge_client_mutation_settlements(
        &mut self,
        auth: Option<&AuthInput>,
    ) -> SnapbackResult<u64> {
        let Some(auth) = auth else {
            return self.db.purge_client_mutation_settlements(None);
        };
        let current = self
            .db
            .purge_client_mutation_settlements(Some(&auth_fingerprint(auth)))?;
        let legacy = self
            .db
            .purge_client_mutation_settlements(Some(&legacy_auth_fingerprint(auth)))?;
        current.checked_add(legacy).ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_CLIENT_MUTATION_RETENTION_STATE_INVALID",
                "storage",
                "purged settlement count overflowed across auth aliases",
            )
        })
    }

    pub fn function_definition(&self, name: &str) -> Option<&FunctionDefinition> {
        self.functions.function(name)
    }

    pub fn inspect(&mut self) -> SnapbackResult<InspectState> {
        let mut inspect = self.inspect_core()?;
        inspect.ephemeral = self.ephemeral.diagnostics();
        Ok(inspect)
    }

    /// Capture Local/SQLite-owned inspect state only. Managed server callers
    /// release Local before composing [`EphemeralDiagnostics`] on their
    /// blocking owner; direct-library [`Self::inspect`] remains synchronous.
    pub(crate) fn inspect_core(&mut self) -> SnapbackResult<InspectState> {
        // @ref LLP 0010#v0-implementation-charter — missing non-v0 capabilities must be reported explicitly.
        let capability_gaps = self.capability_gaps();
        let capability_manifest = self.served_capability_manifest(capability_gaps.clone());
        let active_live_functions = self.active_live_functions();
        let cron = self
            .cron
            .inspect(&self.functions, &active_live_functions, now_millis());

        Ok(InspectState {
            artifact_kind: "runtimeState".to_owned(),
            schema_version: SNAPBACK_SCHEMA_VERSION.to_owned(),
            target_profile_id: TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
            target: TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
            storage: self.db.info()?,
            runtime: self.runtime.capabilities().clone(),
            schema: self.db.schema().clone(),
            functions: self.functions.clone(),
            capability_manifest,
            route_manifest_hash: self
                .routes_manifest_hash
                .clone()
                .unwrap_or_else(|| "absent".to_owned()),
            subscriptions: self
                .subscriptions
                .values()
                .map(|subscription| LiveSubscriptionInfo {
                    id: subscription.id.clone(),
                    connection_id: subscription.connection_id.clone(),
                    function: subscription.function.clone(),
                })
                .collect(),
            active_connections: self.connections_last_seen.len(),
            reaped_connections: self.reaped_connections,
            live_delivery: self.live_delivery.clone(),
            ephemeral: EphemeralDiagnostics::default(),
            cron,
            maintenance: self.maintenance.clone(),
            telemetry: self.telemetry.diagnostics(),
            push_registry: self.db.push_registry_inspection()?,
            recent_diagnostics: self.recent_diagnostics.iter().cloned().collect(),
            capability_gaps,
        })
    }

    /// Compose the served capability manifest from this exact process's live
    /// facts: the shared instance constructor plus the post-construction
    /// warm-VM lifecycle override. Every reporting seam (`/inspect`, the RQS
    /// generation identity) goes through this one helper so the override
    /// cannot drift between seams
    /// (issues/20260729-centralize-served-capability-manifest-composition.md).
    // @ref LLP 0076#target-contract — the served manifest is instance-live:
    // it reflects whether THIS process enabled outbound egress and so the
    // bounded response-stream profile, not the conservative declaration.
    fn served_capability_manifest(&self, capability_gaps: Vec<String>) -> CapabilityManifest {
        let mut capability_manifest = CapabilityManifest::local_v0_instance(
            capability_gaps,
            crate::runtime::outbound_actions_enabled(),
        );
        // @ref LLP 0009#dk-4-retired--upstream-ibex-owner-thread-contract-2026-07-27 —
        // report the lifecycle policy honestly. The compatibility branch is
        // retained for older policy implementations.
        if self.warm_vms.enabled() {
            capability_manifest.vm_lifecycle =
                crate::manifest::VM_LIFECYCLE_WARM_POOLED_RESET.to_owned();
        }
        capability_manifest
    }

    fn capability_gaps(&self) -> Vec<String> {
        // The declared gap list is owned by the manifest module (the single
        // source the committed capability artifact is generated from —
        // LLP 0032 P2); only instance-live adjustments happen here.
        let mut capability_gaps = crate::manifest::local_v0_default_capability_gaps();
        if self.runtime.capabilities().ibex_cli.available {
            capability_gaps.retain(|gap| gap != "ibex_cli");
        } else {
            capability_gaps.push("ibex_cli".to_owned());
        }
        if crate::runtime::outbound_actions_enabled() {
            capability_gaps
                .retain(|gap| gap != "outbound_actions" && gap != "bounded_response_stream_v1");
        }
        capability_gaps
    }

