/// The one-transaction deletion cascade (LLP 0044 §Lifecycle transitions):
/// fence the current attempt, retire every rendition row, decrement each
/// rendition's blob reference — the primary exactly once, because primary
/// bytes are only the `primary` rendition record — and transit the asset,
/// whose generation bump fences in-flight work at its next generation
/// check. Logical quota releases at this commit because settled usage
/// counts only live renditions. Returns the fenced staging key; the caller
/// removes the file after commit (orphans belong to the sweep).
fn asset_delete_cascade(
    tx: &rusqlite::Transaction<'_>,
    asset: &mut crate::assets::AssetRecordV1,
    cause: &str,
    now_ms: u64,
) -> SnapbackResult<Option<String>> {
    use crate::assets;
    let mut fenced_staging = None;
    if let Some(mut attempt) = assets::current_attempt(tx, &asset.asset_id)? {
        assets::transition_attempt(
            tx,
            &mut attempt,
            assets::AssetAttemptState::Cancelled,
            now_ms,
        )?;
        assets::write_receipt(
            tx,
            &asset_receipt(
                &attempt.attempt_id.clone(),
                assets::AssetReceiptEventV1::AttemptCancelled,
                &asset.asset_id,
                Some(&attempt.attempt_id),
                now_ms,
                serde_json::json!({ "cause": cause }),
            ),
        )?;
        fenced_staging = Some(attempt.staging_key);
    }
    let mut renditions_retired = 0u64;
    let mut blobs_released = Vec::new();
    for mut rendition in assets::renditions_for_asset(tx, &asset.asset_id)? {
        use crate::assets::AssetRenditionState as R;
        if rendition.state == R::Retired {
            continue;
        }
        // Failed renditions hold no committed blob reference (their
        // publication was condemned); every other live state does.
        let holds_reference = matches!(rendition.state, R::Pending | R::Ready | R::Superseded);
        assets::transition_rendition(tx, &mut rendition, R::Retired, now_ms)?;
        if holds_reference {
            let remaining = assets::release_blob_reference(tx, &rendition.blob_id, now_ms)?;
            blobs_released.push(serde_json::json!({
                "blobId": rendition.blob_id,
                "remainingReferences": remaining,
            }));
        }
        renditions_retired += 1;
    }
    assets::transition_asset(tx, asset, assets::AssetAvailability::Deleted, now_ms)?;
    assets::write_receipt(
        tx,
        &asset_receipt(
            &asset.asset_id.clone(),
            assets::AssetReceiptEventV1::AssetDeleted,
            &asset.asset_id,
            None,
            now_ms,
            serde_json::json!({
                "cause": cause,
                "renditionsRetired": renditions_retired,
                "blobsReleased": blobs_released,
            }),
        ),
    )?;
    Ok(fenced_staging)
}

fn asset_planned_publication(
    app_id: &str,
    attempt_id: &str,
    digest: &str,
    now_ms: u64,
) -> crate::assets::AssetPublicationRecordV1 {
    crate::assets::AssetPublicationRecordV1 {
        publication_id: crate::assets::AssetFsStore::new_opaque_key(),
        app_id: app_id.to_owned(),
        attempt_id: Some(attempt_id.to_owned()),
        planned_key: crate::assets::AssetFsStore::new_opaque_key(),
        digest_algorithm: crate::assets::ASSET_DIGEST_ALGORITHM_SHA256.to_owned(),
        digest: digest.to_owned(),
        canonicalization_policy: crate::assets::ASSET_CANONICALIZATION_NONE.to_owned(),
        state: crate::assets::AssetPublicationState::Planned,
        generation: 1,
        blob_id: None,
        created_at_ms: now_ms,
        updated_at_ms: now_ms,
    }
}

fn asset_hash_bytes(bytes: &[u8]) -> String {
    use sha2::Digest as _;
    let mut hasher = sha2::Sha256::new();
    hasher.update(bytes);
    hasher
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// A rendered variant staged through the write-ahead publication protocol:
/// the object exists and verifies under a `staged` record; the commit half
/// (`asset_commit_prepared_variant`) runs inside the publishing transaction.
#[derive(Clone)]
struct AssetPreparedVariant {
    key: String,
    width: u64,
    publication: crate::assets::AssetPublicationRecordV1,
    digest: String,
    byte_length: u64,
    content_type: String,
    recipe_version: u64,
}

enum AssetVariantCommit {
    Committed {
        rendition_id: String,
    },
    /// An idempotent re-drive: a Ready same-lineage rendition already holds
    /// the pointer; our duplicate publication condemns with tracked cleanup.
    AlreadyCurrent,
    /// Settlement would exceed the app quota: a structured rendition
    /// failure, gating `ready` only when the variant is required.
    QuotaRefused,
    /// A newer recipe version holds the pointer; the stale run loses and
    /// its publication condemns.
    StaleLost,
}

fn asset_commit_prepared_variant(
    tx: &rusqlite::Transaction<'_>,
    app_id: &str,
    asset_id: &str,
    prepared: &AssetPreparedVariant,
    app_quota: u64,
    now: u64,
) -> SnapbackResult<AssetVariantCommit> {
    use crate::assets;
    let mut publication = prepared.publication.clone();
    let condemn = |tx: &rusqlite::Transaction<'_>,
                   publication: &mut assets::AssetPublicationRecordV1|
     -> SnapbackResult<()> {
        assets::transition_publication(
            tx,
            publication,
            assets::AssetPublicationState::Condemned,
            now,
        )?;
        assets::enqueue_work(
            tx,
            assets::ASSET_WORK_KIND_CONDEMNED_CLEANUP,
            asset_id,
            None,
            0,
            now,
        )?;
        Ok(())
    };

    let accounting = assets::asset_accounting(tx, app_id)?;
    let increment = prepared
        .byte_length
        .max(assets::ASSET_MIN_ACCOUNTING_UNIT_BYTES);
    let in_use = accounting
        .reserved_bytes
        .saturating_add(accounting.settled_bytes);
    if in_use.saturating_add(increment) > app_quota {
        condemn(tx, &mut publication)?;
        return Ok(AssetVariantCommit::QuotaRefused);
    }

    let blob_record = assets::AssetBlobRecordV1 {
        blob_id: assets::AssetFsStore::new_opaque_key(),
        app_id: app_id.to_owned(),
        store: assets::ASSET_STORE_LOCAL_FS.to_owned(),
        physical_key: publication.planned_key.clone(),
        byte_length: prepared.byte_length,
        detected_content_type: prepared.content_type.clone(),
        digest_algorithm: assets::ASSET_DIGEST_ALGORITHM_SHA256.to_owned(),
        digest: prepared.digest.clone(),
        canonicalization_policy: assets::ASSET_CANONICALIZATION_NONE.to_owned(),
        created_at_ms: now,
    };
    let blob_id = match assets::insert_blob(tx, &blob_record, now)? {
        assets::BlobInsertOutcome::Created => {
            publication.blob_id = Some(blob_record.blob_id.clone());
            assets::transition_publication(
                tx,
                &mut publication,
                assets::AssetPublicationState::Committed,
                now,
            )?;
            blob_record.blob_id.clone()
        }
        assets::BlobInsertOutcome::ConvergedOnWinner { blob_id } => {
            condemn(tx, &mut publication)?;
            blob_id
        }
    };

    let rendition = assets::AssetRenditionRecordV1 {
        rendition_id: assets::AssetFsStore::new_opaque_key(),
        asset_id: asset_id.to_owned(),
        variant_key: prepared.key.clone(),
        blob_id: blob_id.clone(),
        state: assets::AssetRenditionState::Ready,
        recipe: assets::ASSET_RECIPE_IMAGE_VARIANT_V1.to_owned(),
        recipe_version: prepared.recipe_version,
        media_facts: Some(serde_json::json!({
            "contentType": prepared.content_type,
            "byteLength": prepared.byte_length,
            "width": prepared.width,
        })),
        created_at_ms: now,
        updated_at_ms: now,
        failure: None,
    };
    match assets::switch_variant_pointer(tx, &rendition, now)? {
        assets::AssetVariantSwitchOutcome::Installed => Ok(AssetVariantCommit::Committed {
            rendition_id: rendition.rendition_id,
        }),
        outcome @ (assets::AssetVariantSwitchOutcome::AlreadyCurrent
        | assets::AssetVariantSwitchOutcome::StaleLoses) => {
            // No rendition row took our reference: whether the blob was
            // freshly created (refcount 1) or converged onto the winner
            // (incremented), the acquired reference releases here. A
            // freshly created blob goes to zero references and blob GC
            // condemns it through its ordinary transactional path — the
            // committed publication record retires on retention, it does
            // not condemn (its closed set has no committed → condemned).
            assets::release_blob_reference(tx, &blob_id, now)?;
            Ok(match outcome {
                assets::AssetVariantSwitchOutcome::AlreadyCurrent => {
                    AssetVariantCommit::AlreadyCurrent
                }
                _ => AssetVariantCommit::StaleLost,
            })
        }
    }
}

fn asset_receipt(
    lineage: &str,
    event: crate::assets::AssetReceiptEventV1,
    asset_id: &str,
    attempt_id: Option<&str>,
    at_ms: u64,
    details: serde_json::Value,
) -> crate::assets::AssetReceiptV1 {
    crate::assets::AssetReceiptV1 {
        receipt_id: crate::assets::AssetFsStore::new_opaque_key(),
        operation_lineage: lineage.to_owned(),
        event,
        asset_id: Some(asset_id.to_owned()),
        attempt_id: attempt_id.map(str::to_owned),
        at_ms,
        details,
    }
}

fn asset_task_state(
    attempt: &crate::assets::AssetAttemptRecordV1,
    asset: Option<&crate::assets::AssetRecordV1>,
) -> crate::assets::AssetTaskStateV1 {
    crate::assets::AssetTaskStateV1 {
        asset_id: attempt.asset_id.clone(),
        attempt_id: attempt.attempt_id.clone(),
        attempt_state: attempt.state,
        availability: asset
            .map(|asset| asset.availability)
            .unwrap_or(crate::assets::AssetAvailability::Pending),
        acknowledged_offset: attempt.acknowledged_offset,
        total_bytes: attempt.declared_length,
        expires_at_ms: attempt.expires_at_ms,
        integrity_grade: attempt.integrity_grade,
        primary_rendition_id: asset.and_then(|asset| asset.primary_rendition_id.clone()),
        diagnostic: attempt.failure.clone(),
    }
}

fn asset_ceiling_error(what: &str, limit: u64, observed: u64) -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_ASSET_CEILING_EXCEEDED",
        "assets",
        format!("the {what} ceiling is reached"),
    )
    .with_details(serde_json::json!({ "limit": limit, "observed": observed }))
}

fn asset_terminal_error(attempt: &crate::assets::AssetAttemptRecordV1) -> SnapbackError {
    if attempt.state == crate::assets::AssetAttemptState::Expired {
        SnapbackError::error(
            "SNAPBACK_ASSET_ATTEMPT_EXPIRED",
            "assets",
            "this attempt expired; request a fresh one (retry preserves the asset id)",
        )
    } else {
        SnapbackError::error(
            "SNAPBACK_ASSET_ATTEMPT_TERMINAL",
            "assets",
            format!("attempt is terminal ({})", attempt.state.as_str()),
        )
    }
}

/// Media-type admission over the intent's accept list, honoring `type/*`
/// wildcards the way generation-time admission does.
fn asset_media_type_admitted(accepted: &[String], declared: &str) -> bool {
    let declared = declared
        .split(';')
        .next()
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase();
    accepted.iter().any(|entry| {
        let entry = entry.to_ascii_lowercase();
        entry == declared
            || entry
                .strip_suffix("/*")
                .is_some_and(|prefix| declared.starts_with(&format!("{prefix}/")))
    })
}

fn finish_function_observation<T>(
    span: crate::telemetry::ObservationSpan,
    result: &mut SnapbackResult<T>,
) {
    match result {
        Ok(_) => span.finish(Some(200), None, None),
        Err(error) => {
            let severity = error.diagnostic.severity.clone();
            span.finish_error(Some(500), error, Some(json!({ "severity": severity })))
        }
    }
}

fn telemetry_correlation(value: &Option<Value>) -> Option<String> {
    value.as_ref().and_then(Value::as_str).map(str::to_owned)
}

/// Append one verified chunk to restricted staging at the exact offset,
/// durably (flush + fsync) before the acknowledged offset advances.
fn now_millis() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

fn auth_resnapshot_required() -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_AUTH_RESNAPSHOT_REQUIRED",
        "auth",
        "the authorization scope is unknown, retired, or belongs to an extinct connection; establish a fresh snapshot",
    )
    .with_details(json!({ "reason": "unknownOrReaped" }))
}

fn live_owner_mismatch(subscription_id: &str, authority: &PreparedAuthority) -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_LIVE_RESUME_OWNERSHIP",
        "realtime",
        format!("subscription {subscription_id} is owned by a different live owner"),
    )
    .with_details(json!({
        "subscriptionId": subscription_id,
        // The caller already knows whether it presented an identity. Expose
        // only that presence fact, never either resolved identity. This turns
        // a misplaced/omitted body `auth` into a diagnosable shape error while
        // preserving the retained owner's privacy.
        "presentedIdentity": authority
            .resolved()
            .carries_user()
            .then_some(json!({ "present": true })),
        "expectedIdentity": "[redacted]",
    }))
}

