    const ASSET_INTENT_SOURCE: &str = r#"
globalThis.__snapbackHandlers = {
  async avatarUpload(ctx) {
    return { owner: (ctx.auth && ctx.auth.userId) ? ctx.auth.userId : "owner_1" };
  }
};
"#;

    fn asset_test_intent() -> crate::manifest::AssetUploadIntentDefinition {
        crate::manifest::AssetUploadIntentDefinition {
            id: "app:avatarUpload".to_owned(),
            name: "avatarUpload".to_owned(),
            exported_name: Some("avatarUpload".to_owned()),
            implementation_hash: Some("sha256:test-impl".to_owned()),
            args_contract_hash: Some("sha256:test-args".to_owned()),
            intent_policy_hash: "sha256:test-policy".to_owned(),
            auth_requirement: None,
            accept: crate::manifest::AssetAcceptPolicy {
                media_types: vec!["application/octet-stream".to_owned()],
                max_bytes: 64 * 1024,
            },
            delivery: crate::manifest::AssetDeliveryPolicy {
                kind: crate::assets::AssetDeliveryProfile::PrivateStrict,
            },
            access: crate::manifest::AssetAccessPolicy {
                read: crate::assets::AssetReadAccessPolicy::OwnerOnly,
            },
            image: None,
            on: None,
            declared_reads: Vec::new(),
            runtime: FunctionRuntime::IbexModule(IbexModule {
                source: ASSET_INTENT_SOURCE.to_owned(),
                export: "avatarUpload".to_owned(),
            }),
            handler_form: Some("inline".to_owned()),
            source_span: None,
        }
    }

    fn asset_test_snapback() -> LocalSnapback {
        let mut snapback = LocalSnapback::memory().expect("memory snapback");
        let diagnostics = snapback.load_functions(FunctionManifest {
            asset_upload_intents: vec![asset_test_intent()],
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "intent manifest must load: {diagnostics:?}"
        );
        snapback
    }

    #[test]
    fn asset_cut_exports_and_restores_onto_an_empty_instance() {
        let scratch = tempfile::tempdir().expect("tempdir");
        let export_dir = scratch.path().join("cut");
        let export_dir_str = export_dir.to_string_lossy().into_owned();

        let mut source = asset_profile_snapback();
        let kept = asset_ready_under_intent(&mut source, "alice", b"cut bytes one", "signedUpload");
        let doomed =
            asset_ready_under_intent(&mut source, "alice", b"cut bytes two", "publicUpload");
        let deleter = asset_dev_authority(&source, "alice", InvocationSource::HttpQuery);
        source
            .asset_delete(&deleter, &doomed)
            .expect("delete tombstones");
        let source_generation = source
            .db
            .asset_transaction(|tx| crate::assets::load_asset(tx, &kept))
            .expect("load")
            .expect("kept exists")
            .lifecycle_generation;

        let exported = source
            .asset_host_op(
                "asset.exportCut",
                Some(&serde_json::json!({ "dir": export_dir_str })),
                None,
                ServerProfile::Dev,
            )
            .expect("export succeeds");
        assert_eq!(exported["cut"]["assetCount"], 1);
        assert_eq!(exported["cut"]["tombstoneCount"], 1);
        assert!(exported["cut"]["blobCount"].as_u64().unwrap() >= 1);

        // Export receipts: the instance-scoped CutExported event landed.
        let receipt_events: Vec<String> = source
            .db
            .asset_transaction(|tx| {
                let mut statement = tx
                    .prepare("SELECT record_json FROM _snapback_asset_receipts_v1")
                    .expect("prepare");
                let rows = statement
                    .query_map([], |row| row.get::<_, String>(0))
                    .expect("query");
                Ok(rows
                    .filter_map(|row| row.ok())
                    .filter(|json| json.contains("cut-exported"))
                    .collect())
            })
            .expect("receipts");
        assert!(!receipt_events.is_empty(), "CutExported receipt written");

        let mut restored = asset_profile_snapback();
        let validated = restored
            .asset_host_op(
                "asset.importCut",
                Some(&serde_json::json!({ "dir": export_dir_str })),
                None,
                ServerProfile::Dev,
            )
            .expect("validate succeeds");
        assert_eq!(validated["applied"], false);

        let refused = restored
            .asset_host_op(
                "asset.importCut",
                Some(&serde_json::json!({ "dir": export_dir_str, "apply": true })),
                None,
                ServerProfile::Dev,
            )
            .expect_err("apply without acknowledgement refuses");
        assert_eq!(
            refused.diagnostic.code,
            "SNAPBACK_ASSET_IMPORT_EXPERIMENTAL_REQUIRED"
        );

        restored.set_asset_import_experimental_override(true);
        let applied = restored
            .asset_host_op(
                "asset.importCut",
                Some(&serde_json::json!({ "dir": export_dir_str, "apply": true })),
                None,
                ServerProfile::Dev,
            )
            .expect("apply succeeds");
        assert_eq!(applied["applied"], true);

        // Restore-epoch fence: the imported generation is the exported one
        // plus one, and the tombstone stayed dead.
        let (restored_record, tombstone) = restored
            .db
            .asset_transaction(|tx| {
                Ok((
                    crate::assets::load_asset(tx, &kept)?.expect("kept restored"),
                    crate::assets::load_asset(tx, &doomed)?.expect("tombstone restored"),
                ))
            })
            .expect("load restored");
        assert_eq!(
            restored_record.lifecycle_generation,
            source_generation + 1,
            "restore bumps the lifecycle generation"
        );
        assert_eq!(
            tombstone.availability,
            crate::assets::AssetAvailability::Deleted
        );

        // The restored asset serves real bytes through ordinary delivery.
        let delivered = asset_deliver_content(&mut restored, "alice", &kept, "primary", None)
            .expect("restored asset delivers");
        assert_eq!(delivered.total_length, b"cut bytes one".len() as u64);

        // A second apply refuses: the target is no longer empty.
        let occupied = restored
            .asset_host_op(
                "asset.importCut",
                Some(&serde_json::json!({ "dir": export_dir_str, "apply": true })),
                None,
                ServerProfile::Dev,
            )
            .expect_err("non-empty target refuses");
        assert_eq!(
            occupied.diagnostic.code,
            "SNAPBACK_ASSET_IMPORT_TARGET_NOT_EMPTY"
        );
    }

    #[test]
    fn asset_cut_import_refuses_missing_and_tampered_blob_objects() {
        let scratch = tempfile::tempdir().expect("tempdir");
        let export_dir = scratch.path().join("cut");
        let export_dir_str = export_dir.to_string_lossy().into_owned();

        let mut source = asset_profile_snapback();
        asset_ready_under_intent(&mut source, "alice", b"tamper target", "signedUpload");
        source
            .asset_host_op(
                "asset.exportCut",
                Some(&serde_json::json!({ "dir": export_dir_str })),
                None,
                ServerProfile::Dev,
            )
            .expect("export succeeds");

        let blob_dir = export_dir.join(crate::assets_cut::ASSET_CUT_BLOB_DIR);
        let blob_file = std::fs::read_dir(&blob_dir)
            .expect("blob dir")
            .next()
            .expect("one blob")
            .expect("entry")
            .path();

        // Tampered bytes: digest mismatch refuses before any row lands.
        let original = std::fs::read(&blob_file).expect("read blob");
        let mut tampered = original.clone();
        tampered.push(0xAA);
        std::fs::write(&blob_file, &tampered).expect("tamper");
        let mut restored = asset_profile_snapback();
        restored.set_asset_import_experimental_override(true);
        let mismatch = restored
            .asset_host_op(
                "asset.importCut",
                Some(&serde_json::json!({ "dir": export_dir_str, "apply": true })),
                None,
                ServerProfile::Dev,
            )
            .expect_err("tampered blob refuses");
        assert_eq!(
            mismatch.diagnostic.code,
            "SNAPBACK_ASSET_IMPORT_DIGEST_MISMATCH"
        );

        // Missing object: refuse-partial.
        std::fs::remove_file(&blob_file).expect("remove blob");
        let incomplete = restored
            .asset_host_op(
                "asset.importCut",
                Some(&serde_json::json!({ "dir": export_dir_str })),
                None,
                ServerProfile::Dev,
            )
            .expect_err("missing blob refuses");
        assert_eq!(
            incomplete.diagnostic.code,
            "SNAPBACK_ASSET_IMPORT_INCOMPLETE"
        );

        // Nothing landed on the refused instance.
        let empty = restored
            .db
            .asset_transaction(|tx| {
                tx.query_row(
                    "SELECT COUNT(*) FROM _snapback_asset_records_v1",
                    [],
                    |row| row.get::<_, u64>(0),
                )
                .map_err(crate::diagnostic::SnapbackError::from)
            })
            .expect("count");
        assert_eq!(empty, 0, "refuse-partial lands no rows");
    }

    fn asset_dev_authority(
        snapback: &LocalSnapback,
        user: &str,
        source: InvocationSource,
    ) -> PreparedAuthority {
        let input = HandlerInput {
            auth: crate::manifest::AuthInput {
                user_id: Some(user.to_owned()),
                ..Default::default()
            },
            ..Default::default()
        };
        InvocationGate::prepare_admitted_dev_input(
            source,
            ServerProfile::Dev,
            &input,
            snapback.admission.admit_dev().expect("dev admission"),
        )
        .expect("dev authority")
    }

    fn asset_create_request(length: Option<u64>) -> crate::assets::AssetAttemptCreateRequestV1 {
        crate::assets::AssetAttemptCreateRequestV1 {
            intent_id: "app:avatarUpload".to_owned(),
            intent_policy_hash: "sha256:test-policy".to_owned(),
            args: serde_json::json!({}),
            declared_filename: Some("photo.bin".to_owned()),
            declared_length: length,
            declared_content_type: Some("application/octet-stream".to_owned()),
            retry_of_asset_id: None,
        }
    }

    fn asset_chunk_checksum(chunk: &[u8]) -> String {
        use sha2::Digest as _;
        base64::Engine::encode(
            &base64::engine::general_purpose::STANDARD,
            sha2::Sha256::digest(chunk),
        )
    }

    #[test]
    fn asset_attempt_lifecycle_creates_transfers_resumes_and_cancels() {
        let mut snapback = asset_test_snapback();
        let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
        let transfer = asset_dev_authority(&snapback, "user_a", InvocationSource::AssetTransfer);

        let response = snapback
            .asset_attempt_create(&creator, asset_create_request(Some(10)))
            .expect("attempt creates");
        assert_eq!(response.transfer.tus_resumable, "1.0.0");
        assert_eq!(
            response.task.attempt_state,
            crate::assets::AssetAttemptState::Open
        );
        // The authorizer's owner is the caller's dev identity, captured with
        // a witness (auth facts at minimum) and the frozen policy identity.
        let attempt_id = response.task.attempt_id.clone();

        let chunk1 = b"hello";
        let attempt = snapback
            .asset_tus_patch(
                &transfer,
                &attempt_id,
                0,
                chunk1,
                Some(("sha256", &asset_chunk_checksum(chunk1))),
            )
            .expect("first chunk lands");
        assert_eq!(attempt.acknowledged_offset, 5);
        assert_eq!(
            attempt.state,
            crate::assets::AssetAttemptState::Transferring
        );
        assert!(attempt.all_chunks_checksummed);
        assert_eq!(attempt.admission.owner_principal, "user_a");

        // Offset conflict refuses without applying bytes.
        let conflict = snapback
            .asset_tus_patch(&transfer, &attempt_id, 3, b"xx", None)
            .expect_err("offset conflict refuses");
        assert_eq!(conflict.diagnostic.code, "SNAPBACK_ASSET_OFFSET_CONFLICT");

        // Resume from the acknowledged offset (HEAD is the resume probe).
        let head = snapback
            .asset_tus_head(&transfer, &attempt_id)
            .expect("head resumes");
        assert_eq!(head.acknowledged_offset, 5);

        let chunk2 = b"world";
        let attempt = snapback
            .asset_tus_patch(
                &transfer,
                &attempt_id,
                5,
                chunk2,
                Some(("sha256", &asset_chunk_checksum(chunk2))),
            )
            .expect("second chunk lands");
        assert_eq!(attempt.acknowledged_offset, 10);

        // The staging bytes are exactly the appended stream.
        let store = snapback.asset_store().expect("store");
        let staged = std::fs::read(store.staging_path(&attempt.staging_key).unwrap()).unwrap();
        assert_eq!(staged, b"helloworld");

        let task = snapback
            .asset_attempt_cancel(
                &transfer,
                crate::assets::AssetAttemptCancelRequestV1 {
                    attempt_id: attempt_id.clone(),
                    lifecycle_generation: attempt.lifecycle_generation,
                    discard_asset: true,
                },
            )
            .expect("cancel-and-discard");
        assert_eq!(
            task.attempt_state,
            crate::assets::AssetAttemptState::Cancelled
        );
        assert_eq!(task.availability, crate::assets::AssetAvailability::Deleted);
        assert!(!store.staging_path(&attempt.staging_key).unwrap().exists());
    }

    #[test]
    fn asset_attempt_refusals_are_structured() {
        let mut snapback = asset_test_snapback();
        let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

        // Deferred length is a structured refusal, not a parse error.
        let error = snapback
            .asset_attempt_create(&creator, asset_create_request(None))
            .expect_err("deferred length refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_ASSET_DEFERRED_LENGTH_UNSUPPORTED"
        );

        // A stale generated reference refuses before staging.
        let mut stale = asset_create_request(Some(1));
        stale.intent_policy_hash = "sha256:old-policy".to_owned();
        let error = snapback
            .asset_attempt_create(&creator, stale)
            .expect_err("stale reference refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_INTENT_STALE");

        // Media bounds and accept-list enforcement.
        let error = snapback
            .asset_attempt_create(&creator, asset_create_request(Some(1024 * 1024)))
            .expect_err("over-bounds refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_ASSET_MEDIA_BOUNDS_EXCEEDED"
        );
        let mut wrong_type = asset_create_request(Some(1));
        wrong_type.declared_content_type = Some("video/mp4".to_owned());
        let error = snapback
            .asset_attempt_create(&creator, wrong_type)
            .expect_err("undeclared media type refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_ASSET_MEDIA_TYPE_UNSUPPORTED"
        );

        let error = snapback
            .asset_intent("missing")
            .expect_err("unknown intent");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_INTENT_UNKNOWN");
    }

    #[test]
    fn asset_retry_supersedes_and_lineage_gates_access() {
        let mut snapback = asset_test_snapback();
        let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
        let transfer = asset_dev_authority(&snapback, "user_a", InvocationSource::AssetTransfer);
        let stranger = asset_dev_authority(&snapback, "user_b", InvocationSource::AssetTransfer);

        let first = snapback
            .asset_attempt_create(&creator, asset_create_request(Some(10)))
            .expect("first attempt");

        // Possession of the attempt URL is not authority.
        let error = snapback
            .asset_tus_head(&stranger, &first.task.attempt_id)
            .expect_err("foreign caller refused");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");

        // Retry supersedes: same asset id, predecessor cancelled in the same
        // transaction, successor open.
        let mut retry = asset_create_request(Some(10));
        retry.retry_of_asset_id = Some(first.task.asset_id.clone());
        let second = snapback
            .asset_attempt_create(&creator, retry)
            .expect("successor attempt");
        assert_eq!(second.task.asset_id, first.task.asset_id);
        assert_ne!(second.task.attempt_id, first.task.attempt_id);
        let predecessor = snapback
            .asset_tus_head(&transfer, &first.task.attempt_id)
            .expect_err("superseded predecessor is terminal");
        assert_eq!(
            predecessor.diagnostic.code,
            "SNAPBACK_ASSET_ATTEMPT_TERMINAL"
        );
    }

    #[test]
    fn asset_checksums_gate_chunks_and_grade_basis_demotes_without_them() {
        let mut snapback = asset_test_snapback();
        let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
        let transfer = asset_dev_authority(&snapback, "user_a", InvocationSource::AssetTransfer);
        let created = snapback
            .asset_attempt_create(&creator, asset_create_request(Some(10)))
            .expect("attempt");
        let attempt_id = created.task.attempt_id;

        let error = snapback
            .asset_tus_patch(
                &transfer,
                &attempt_id,
                0,
                b"hello",
                Some(("sha256", "bogus")),
            )
            .expect_err("bad checksum refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_ASSET_CHUNK_CHECKSUM_INVALID"
        );
        let error = snapback
            .asset_tus_patch(&transfer, &attempt_id, 0, b"hello", Some(("crc32", "AAAA")))
            .expect_err("unsupported algorithm refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_ASSET_CHUNK_CHECKSUM_INVALID"
        );
        let head = snapback
            .asset_tus_head(&transfer, &attempt_id)
            .expect("offset unchanged after refusals");
        assert_eq!(head.acknowledged_offset, 0);

        // A checksum-less chunk is admitted but demotes the grade basis
        // (LLP 0044: the weaker grade is never reported as the stronger).
        let attempt = snapback
            .asset_tus_patch(&transfer, &attempt_id, 0, b"hello", None)
            .expect("checksum-less chunk admitted");
        assert!(!attempt.all_chunks_checksummed);
    }

    #[test]
    fn asset_per_principal_ceiling_refuses_structured() {
        let mut snapback = asset_test_snapback();
        let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
        for _ in 0..crate::assets::ASSET_MAX_OPEN_ATTEMPTS_PER_PRINCIPAL {
            snapback
                .asset_attempt_create(&creator, asset_create_request(Some(1)))
                .expect("attempt under the ceiling");
        }
        let error = snapback
            .asset_attempt_create(&creator, asset_create_request(Some(1)))
            .expect_err("ceiling refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_CEILING_EXCEEDED");
    }

    #[test]
    fn asset_expired_attempt_refuses_and_receipts() {
        let mut snapback = asset_test_snapback();
        let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
        let transfer = asset_dev_authority(&snapback, "user_a", InvocationSource::AssetTransfer);
        let created = snapback
            .asset_attempt_create(&creator, asset_create_request(Some(10)))
            .expect("attempt");
        let attempt_id = created.task.attempt_id;

        // Force the TTL into the past; the next touch lazily expires it.
        snapback
            .db
            .asset_transaction(|tx| {
                let mut attempt =
                    crate::assets::load_attempt(tx, &attempt_id)?.expect("attempt exists");
                attempt.expires_at_ms = 1;
                crate::assets::store_attempt(tx, &attempt)?;
                Ok(())
            })
            .expect("ttl rewind");
        let error = snapback
            .asset_tus_head(&transfer, &attempt_id)
            .expect_err("expired attempt refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_ATTEMPT_EXPIRED");
        let receipts: u64 = snapback
            .db
            .asset_transaction(|tx| {
                Ok(tx.query_row(
                    "SELECT COUNT(*) FROM _snapback_asset_receipts_v1
                     WHERE attempt_id = ?1 AND event = 'attempt-expired'",
                    [&attempt_id],
                    |row| row.get(0),
                )?)
            })
            .expect("receipt count");
        assert_eq!(receipts, 1);
    }

    #[test]
    fn asset_transfer_resumes_across_restart_on_disk() {
        let dir = tempfile::tempdir().expect("tempdir");
        let db_path = dir.path().join("resume.sqlite3");
        let (attempt_id, transfer_user) = {
            let mut snapback = LocalSnapback::open(&db_path).expect("open");
            snapback.load_functions(FunctionManifest {
                asset_upload_intents: vec![asset_test_intent()],
                ..FunctionManifest::default()
            });
            let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
            let transfer =
                asset_dev_authority(&snapback, "user_a", InvocationSource::AssetTransfer);
            let created = snapback
                .asset_attempt_create(&creator, asset_create_request(Some(10)))
                .expect("attempt");
            let chunk = b"hello";
            snapback
                .asset_tus_patch(
                    &transfer,
                    &created.task.attempt_id,
                    0,
                    chunk,
                    Some(("sha256", &asset_chunk_checksum(chunk))),
                )
                .expect("chunk before restart");
            (created.task.attempt_id, "user_a")
        };

        // A fresh process over the same instance resumes from the last
        // acknowledged offset — authority lineage, never a transport
        // connection, is what binds the resume.
        let mut snapback = LocalSnapback::open(&db_path).expect("reopen");
        snapback.load_functions(FunctionManifest {
            asset_upload_intents: vec![asset_test_intent()],
            ..FunctionManifest::default()
        });
        let transfer =
            asset_dev_authority(&snapback, transfer_user, InvocationSource::AssetTransfer);
        let head = snapback
            .asset_tus_head(&transfer, &attempt_id)
            .expect("resume after restart");
        assert_eq!(head.acknowledged_offset, 5);
        let chunk = b"world";
        let attempt = snapback
            .asset_tus_patch(
                &transfer,
                &attempt_id,
                5,
                chunk,
                Some(("sha256", &asset_chunk_checksum(chunk))),
            )
            .expect("tail chunk after restart");
        assert_eq!(attempt.acknowledged_offset, 10);
    }

    // -----------------------------------------------------------------
    // Trusted finalization and the publication protocol (ticket L1-06).
    // -----------------------------------------------------------------

    fn asset_upload(
        snapback: &mut LocalSnapback,
        user: &str,
        bytes: &[u8],
        checksummed: bool,
    ) -> crate::assets::AssetAttemptCreateResponseV1 {
        let creator = asset_dev_authority(snapback, user, InvocationSource::HttpQuery);
        let transfer = asset_dev_authority(snapback, user, InvocationSource::AssetTransfer);
        let created = snapback
            .asset_attempt_create(&creator, asset_create_request(Some(bytes.len() as u64)))
            .expect("attempt creates");
        let checksum = asset_chunk_checksum(bytes);
        snapback
            .asset_tus_patch(
                &transfer,
                &created.task.attempt_id,
                0,
                bytes,
                checksummed.then_some(("sha256", checksum.as_str())),
            )
            .expect("bytes land");
        created
    }

    /// A strict-intent clone with a different id and delivery profile, for
    /// the signed/public delivery-lane suites.
    fn asset_profile_intent(
        name: &str,
        kind: crate::assets::AssetDeliveryProfile,
    ) -> crate::manifest::AssetUploadIntentDefinition {
        let mut intent = asset_test_intent();
        intent.id = format!("app:{name}");
        intent.name = name.to_owned();
        intent.exported_name = Some(name.to_owned());
        intent.intent_policy_hash = format!("sha256:test-policy-{name}");
        intent.delivery = crate::manifest::AssetDeliveryPolicy { kind };
        intent
    }

    fn asset_profile_snapback() -> LocalSnapback {
        let mut snapback = LocalSnapback::memory().expect("memory snapback");
        let diagnostics = snapback.load_functions(FunctionManifest {
            asset_upload_intents: vec![
                asset_test_intent(),
                asset_profile_intent(
                    "signedUpload",
                    crate::assets::AssetDeliveryProfile::PrivateSigned,
                ),
                asset_profile_intent(
                    "publicUpload",
                    crate::assets::AssetDeliveryProfile::PublicImmutable,
                ),
            ],
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "intent manifest must load: {diagnostics:?}"
        );
        snapback
    }

    /// Upload + finalize under a named profile intent; returns the asset id.
    fn asset_ready_under_intent(
        snapback: &mut LocalSnapback,
        user: &str,
        bytes: &[u8],
        name: &str,
    ) -> String {
        let creator = asset_dev_authority(snapback, user, InvocationSource::HttpQuery);
        let transfer = asset_dev_authority(snapback, user, InvocationSource::AssetTransfer);
        let mut request = asset_create_request(Some(bytes.len() as u64));
        request.intent_id = format!("app:{name}");
        request.intent_policy_hash = format!("sha256:test-policy-{name}");
        let created = snapback
            .asset_attempt_create(&creator, request)
            .expect("attempt creates");
        let checksum = asset_chunk_checksum(bytes);
        snapback
            .asset_tus_patch(
                &transfer,
                &created.task.attempt_id,
                0,
                bytes,
                Some(("sha256", checksum.as_str())),
            )
            .expect("bytes land");
        asset_finalize(snapback, user, &created.task.attempt_id, None).expect("finalizes");
        created.task.asset_id
    }

    fn asset_finalize(
        snapback: &mut LocalSnapback,
        user: &str,
        attempt_id: &str,
        declared_digest: Option<String>,
    ) -> SnapbackResult<crate::assets::AssetFinalizeResponseV1> {
        let authority = asset_dev_authority(snapback, user, InvocationSource::HttpQuery);
        snapback.asset_attempt_finalize(
            &authority,
            crate::assets::AssetFinalizeRequestV1 {
                attempt_id: attempt_id.to_owned(),
                lifecycle_generation: 1,
                declared_digest,
            },
        )
    }

    /// posts.photo restricts to the avatarUpload intent and shares
    /// public-read; drafts.pic is restriction-less with no sharing (the
    /// mixed-table stand-in); owned.photo shares through an owner field.
    fn asset_reference_schema() -> SchemaManifest {
        let table = |name: &str,
                     fields: Vec<crate::manifest::FieldManifest>,
                     sharing: Option<crate::manifest::AssetSharingManifest>| {
            crate::manifest::TableManifest {
                name: name.to_owned(),
                fields,
                indexes: Vec::new(),
                syncable: false,
                permission_backing: false,
                permission_fields: None,
                search_indexes: Vec::new(),
                vector_indexes: Vec::new(),
                search_live_limits: None,
                membership: None,
                asset_sharing: sharing,
                history: None,
            }
        };
        let string_field = |name: &str| crate::manifest::FieldManifest {
            name: name.to_owned(),
            field_type: crate::manifest::FieldType::String,
            optional: true,
        };
        let asset_field = |name: &str, upload: Option<&str>| crate::manifest::FieldManifest {
            name: name.to_owned(),
            field_type: crate::manifest::FieldType::AssetRef {
                upload: upload.map(str::to_owned),
            },
            optional: true,
        };
        SchemaManifest {
            tables: vec![
                table(
                    "posts",
                    vec![
                        string_field("title"),
                        asset_field("photo", Some("avatarUpload")),
                    ],
                    Some(crate::manifest::AssetSharingManifest::PublicRead),
                ),
                table("drafts", vec![asset_field("pic", None)], None),
                table(
                    "owned",
                    vec![
                        string_field("ownerId"),
                        asset_field("photo", Some("avatarUpload")),
                    ],
                    Some(crate::manifest::AssetSharingManifest::Owner {
                        field: "ownerId".to_owned(),
                    }),
                ),
            ],
            ..SchemaManifest::default()
        }
    }

    fn asset_reference_snapback() -> LocalSnapback {
        let mut snapback = asset_test_snapback();
        snapback
            .db
            .apply_schema(asset_reference_schema())
            .expect("schema");
        snapback
    }

    fn asset_ready(snapback: &mut LocalSnapback, user: &str, bytes: &[u8]) -> String {
        let created = asset_upload(snapback, user, bytes, true);
        asset_finalize(snapback, user, &created.task.attempt_id, None).expect("finalizes");
        created.task.asset_id
    }

    fn asset_handler_commit(
        snapback: &mut LocalSnapback,
        user: &str,
        writes: Vec<crate::storage::BufferedWrite>,
        admissions: Vec<crate::assets::AssetAttachmentAdmission>,
    ) -> SnapbackResult<crate::storage::MutationCommit> {
        let input = HandlerInput {
            auth: crate::manifest::AuthInput {
                user_id: Some(user.to_owned()),
                ..Default::default()
            },
            ..Default::default()
        };
        let commit = snapback.db.commit_buffered_writes_idempotent_guarded(
            &input,
            crate::storage::BufferedCommitPayload {
                writes,
                sequence_allocations: Vec::new(),
                membership_plans: Vec::new(),
                read_dependencies: Vec::new(),
                result: Value::Null,
                ctx_ledger: crate::manifest::CtxAnswerLedger::default(),
                job_enqueues: Vec::new(),
                job_producer: None,
                asset_admissions: admissions,
            },
            None,
            || Ok(()),
            || Ok(()),
        )?;
        // Mirror the production mutation path's post-commit live fan-out so
        // subscription tests observe what a real handler commit delivers.
        snapback.notify_live_subscriptions(&commit.changes);
        Ok(commit)
    }

    fn asset_edges(
        snapback: &mut LocalSnapback,
        table: &str,
        row_id: &str,
    ) -> Vec<crate::assets::AssetReferenceEdgeV1> {
        snapback
            .db
            .asset_transaction(|tx| crate::assets::load_edges_for_row(tx, table, row_id))
            .expect("edges")
    }

    /// The reference fixture with the app's reference-GC opt-in declared
    /// (LLP 0044 §Deletion: a schema declaration, not an intent knob).
    fn asset_reference_gc_snapback(grace_ms: u64) -> LocalSnapback {
        let mut snapback = asset_test_snapback();
        let mut schema = asset_reference_schema();
        schema.assets = Some(crate::manifest::SchemaAssetsPolicyV1 {
            reference_gc: Some(crate::manifest::AssetReferenceGcPolicyV1 { grace_ms }),
        });
        snapback.db.apply_schema(schema).expect("schema");
        snapback
    }

    fn asset_receipts_with_policy(
        snapback: &mut LocalSnapback,
        asset_id: &str,
        policy: &str,
    ) -> Vec<serde_json::Value> {
        snapback
            .db
            .asset_transaction(|tx| crate::assets::receipts_for_asset(tx, asset_id, 200))
            .expect("receipts")
            .into_iter()
            .filter(|receipt| {
                receipt.event == crate::assets::AssetReceiptEventV1::GcReclaimed
                    && receipt
                        .details
                        .get("policy")
                        .and_then(|value| value.as_str())
                        == Some(policy)
            })
            .map(|receipt| receipt.details)
            .collect()
    }

    #[test]
    fn asset_reference_gc_reclaims_only_unreferenced_ready_past_grace() {
        const GRACE_MS: u64 = 60_000;
        let mut snapback = asset_reference_gc_snapback(GRACE_MS);
        let now = now_millis();

        // A never-attached ready asset starts its clock at publication; a
        // referenced sibling never becomes a candidate.
        let unattached = asset_ready(&mut snapback, "user_a", b"never-attached");
        let attached = asset_ready(&mut snapback, "user_a", b"attached-bytes");
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "posts".to_owned(),
                id: "post_gc".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(attached.clone()))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: attached.clone(),
                upload: Some("avatarUpload".to_owned()),
            }],
        )
        .expect("attach commits");

        // Inside the grace window nothing reclaims.
        let report = snapback.asset_gc_sweep(now + GRACE_MS / 2).expect("sweep");
        assert_eq!(report.reference_reclaimed, 0);

        // Past grace: the unattached asset reclaims with the policy and the
        // grace window on the receipt; the referenced one survives.
        let report = snapback.asset_gc_sweep(now + GRACE_MS * 2).expect("sweep");
        assert_eq!(report.reference_reclaimed, 1);
        let details = asset_receipts_with_policy(&mut snapback, &unattached, "reference-gc");
        assert_eq!(details.len(), 1);
        assert_eq!(details[0]["graceMs"], json!(GRACE_MS));
        let survivor = snapback
            .db
            .asset_transaction(|tx| crate::assets::load_asset(tx, &attached))
            .expect("load")
            .expect("attached asset survives");
        assert_eq!(
            survivor.availability,
            crate::assets::AssetAvailability::Ready
        );

        // Clearing the field starts the clock; re-attaching clears it, so
        // a racing attachment always wins over the sweep.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Patch {
                table: "posts".to_owned(),
                id: "post_gc".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), Value::Null)]),
            }],
            Vec::new(),
        )
        .expect("detach commits");
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Patch {
                table: "posts".to_owned(),
                id: "post_gc".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(attached.clone()))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: attached.clone(),
                upload: Some("avatarUpload".to_owned()),
            }],
        )
        .expect("re-attach commits");
        let report = snapback
            .asset_gc_sweep(now_millis() + GRACE_MS * 3)
            .expect("sweep");
        assert_eq!(
            report.reference_reclaimed, 0,
            "re-attached asset is protected"
        );

        // Detach for good: the clock runs from the removal and the asset
        // reclaims through the ordinary deletion cascade.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Patch {
                table: "posts".to_owned(),
                id: "post_gc".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), Value::Null)]),
            }],
            Vec::new(),
        )
        .expect("final detach commits");
        let report = snapback
            .asset_gc_sweep(now_millis() + GRACE_MS * 4)
            .expect("sweep");
        assert_eq!(report.reference_reclaimed, 1);
        let reclaimed = snapback
            .db
            .asset_transaction(|tx| crate::assets::load_asset(tx, &attached))
            .expect("load");
        assert!(
            reclaimed.is_none()
                || reclaimed.unwrap().availability == crate::assets::AssetAvailability::Deleted,
            "detached asset reclaimed"
        );
    }

    #[test]
    fn asset_gc_sweep_host_op_uses_injected_clock_and_receipts_reclamation() {
        const GRACE_MS: u64 = 60_000;
        let mut snapback = asset_reference_gc_snapback(GRACE_MS);
        let asset_id = asset_ready(&mut snapback, "user_a", b"operator-gc");
        let now_ms = now_millis().saturating_add(GRACE_MS * 2);

        let swept = snapback
            .asset_host_op(
                "asset.gcSweep",
                Some(&serde_json::json!({ "nowMs": now_ms })),
                None,
                ServerProfile::Dev,
            )
            .expect("operator sweep");
        assert_eq!(swept["nowMs"], serde_json::json!(now_ms));
        assert_eq!(swept["report"]["referenceReclaimed"], serde_json::json!(1));
        assert_eq!(
            swept["report"]["publication"]["staged"],
            serde_json::json!(0)
        );

        let receipts = asset_receipts_with_policy(&mut snapback, &asset_id, "reference-gc");
        assert_eq!(receipts.len(), 1, "reclamation is semantically receipted");
        assert_eq!(receipts[0]["graceMs"], serde_json::json!(GRACE_MS));

        // Host operations do not retain a response-replay ledger. The sweep
        // itself is fenced/idempotent: re-driving the identical deterministic
        // input cannot reclaim or receipt the same asset twice.
        let replay = snapback
            .asset_host_op(
                "asset.gcSweep",
                Some(&serde_json::json!({ "nowMs": now_ms })),
                None,
                ServerProfile::Dev,
            )
            .expect("identical sweep re-drive");
        assert_eq!(replay["report"]["referenceReclaimed"], serde_json::json!(0));
        assert_eq!(
            asset_receipts_with_policy(&mut snapback, &asset_id, "reference-gc").len(),
            1
        );

        let ambient_clock = snapback
            .asset_host_op("asset.gcSweep", None, None, ServerProfile::Dev)
            .expect_err("the operator must inject nowMs");
        assert_eq!(
            ambient_clock.diagnostic.code,
            "SNAPBACK_HOST_OP_INPUT_MISSING"
        );

        let out_of_range = snapback
            .asset_host_op(
                "asset.gcSweep",
                Some(&serde_json::json!({
                    "nowMs": crate::manifest::PORTABLE_TIMESTAMP_MAX_MS + 1,
                })),
                None,
                ServerProfile::Dev,
            )
            .expect_err("non-portable clock refused");
        assert_eq!(
            out_of_range.diagnostic.code,
            "SNAPBACK_TIMESTAMP_OUT_OF_RANGE"
        );

        let open_shape = snapback
            .asset_host_op(
                "asset.gcSweep",
                Some(&serde_json::json!({ "nowMs": now_ms, "force": true })),
                None,
                ServerProfile::Dev,
            )
            .expect_err("unknown input siblings refused");
        assert_eq!(
            open_shape.diagnostic.code,
            "SNAPBACK_ASSET_HOST_OP_INPUT_INVALID"
        );
    }

    const ASSET_ATTACH_SOURCE: &str = r#"
globalThis.__snapbackHandlers = {
  async attachPhoto(ctx, args) {
    const admitted = await ctx.assets.attach(args.assetId, { upload: 'avatarUpload' });
    const id = await ctx.db.insert('posts', { title: 'staged', photo: admitted });
    return { id };
  }
};
"#;

    /// Regression for the served-path admission drop found by the Lane-1
    /// conformance vectors: the staged mutation path previews through
    /// `dry_run_buffered_writes_with_jobs`, which discarded handler-recorded
    /// `ctx.assets.attach` admissions, so the canonical handler attach flow
    /// refused `SNAPBACK_ASSET_REF_UNVERIFIED` on a real server while the
    /// direct-commit helper (`asset_handler_commit`) could not observe it.
    #[test]
    fn asset_handler_attach_commits_through_the_staged_mutation_path() {
        let mut snapback = LocalSnapback::memory().expect("memory snapback");
        let diagnostics = snapback.load_functions(FunctionManifest {
            functions: vec![FunctionDefinition::new(
                "attachPhoto",
                FunctionKind::Mutation,
                FunctionRuntime::IbexModule(IbexModule {
                    source: ASSET_ATTACH_SOURCE.to_owned(),
                    export: "attachPhoto".to_owned(),
                }),
            )],
            asset_upload_intents: vec![asset_test_intent()],
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "attach manifest must load: {diagnostics:?}"
        );
        snapback
            .db
            .apply_schema(asset_reference_schema())
            .expect("schema");
        let asset_id = asset_ready(&mut snapback, "alice", b"staged-attach-bytes");

        let (result, _receipt) = snapback.invoke_mutation_recording(
            "attachPhoto",
            HandlerInput {
                args: serde_json::json!({ "assetId": asset_id }),
                auth: crate::manifest::AuthInput {
                    user_id: Some("alice".to_owned()),
                    ..Default::default()
                },
                ..Default::default()
            },
        );
        let output = result.expect("staged handler attach commits");
        let row_id = output.result["id"]
            .as_str()
            .expect("handler returns the inserted row id")
            .to_owned();

        let edges = asset_edges(&mut snapback, "posts", &row_id);
        assert_eq!(edges.len(), 1, "reverse edge commits with the row");
        assert_eq!(edges[0].asset_id, asset_id);
        let committed = snapback
            .db
            .asset_transaction(|tx| crate::assets::receipts_for_asset(tx, &asset_id, 200))
            .expect("receipts")
            .into_iter()
            .any(|receipt| {
                receipt.event == crate::assets::AssetReceiptEventV1::AttachmentCommitted
            });
        assert!(committed, "the attachment-committed receipt lands");
    }

    const APP_REFUSAL_SOURCE: &str = r#"
globalThis.__snapbackHandlers = {
  async declaredRefusal(ctx, args) {
    ctx.refuse('STALE_MOVE', { expected: 1, actual: args.revision });
  },
  async untrackedRefusal(ctx, args) {
    ctx.refuse('STALE_MOVE', { expected: 1, actual: args.revision });
  },
  async undeclaredRefusal(ctx) {
    ctx.refuse('SOMETHING_ELSE', { hidden: 'payload' });
  }
};
"#;

    /// @ref LLP 0108#declared-application-refusals — end to end through the
    /// real served mutation path: a declared code arrives typed with its
    /// payload; an undeclared one folds to the generic failure and its
    /// payload never reaches the caller.
    #[test]
    fn declared_application_refusal_round_trips_and_undeclared_folds() {
        let directory = tempfile::tempdir().expect("refusal telemetry directory");
        let database_path = directory.path().join("refusal-telemetry.sqlite3");
        let mut snapback =
            LocalSnapback::open(&database_path).expect("file-backed refusal snapback");
        let refusal_fn = |name: &str, refusals: Vec<String>, tracked: Vec<String>| {
            let mut definition = FunctionDefinition::new(
                name,
                FunctionKind::Mutation,
                FunctionRuntime::IbexModule(IbexModule {
                    source: APP_REFUSAL_SOURCE.to_owned(),
                    export: name.to_owned(),
                }),
            );
            definition.refusals = refusals;
            definition.tracked_refusals = tracked;
            definition
        };
        let diagnostics = snapback.load_functions(FunctionManifest {
            functions: vec![
                refusal_fn(
                    "declaredRefusal",
                    vec!["STALE_MOVE".to_owned()],
                    vec!["STALE_MOVE".to_owned()],
                ),
                refusal_fn(
                    "untrackedRefusal",
                    vec!["STALE_MOVE".to_owned()],
                    Vec::new(),
                ),
                refusal_fn(
                    "undeclaredRefusal",
                    vec!["STALE_MOVE".to_owned()],
                    Vec::new(),
                ),
            ],
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "refusal manifest must load: {diagnostics:?}"
        );

        let invoke = |snapback: &mut LocalSnapback, name: &str| {
            snapback
                .invoke_mutation_recording(
                    name,
                    HandlerInput {
                        args: serde_json::json!({ "revision": 2 }),
                        ..Default::default()
                    },
                )
                .0
                .expect_err("handler refuses")
        };

        let declared = invoke(&mut snapback, "declaredRefusal");
        assert_eq!(declared.diagnostic.code, "SNAPBACK_APP_REFUSAL");
        assert_eq!(declared.diagnostic.details["appCode"], "STALE_MOVE");
        assert_eq!(declared.diagnostic.details["appDetails"]["actual"], 2);
        assert!(
            declared.private_failure_context().is_none(),
            "the local function observation consumes private tracking state"
        );

        let untracked = invoke(&mut snapback, "untrackedRefusal");
        assert_eq!(untracked.diagnostic.code, "SNAPBACK_APP_REFUSAL");

        let undeclared = invoke(&mut snapback, "undeclaredRefusal");
        assert_eq!(undeclared.diagnostic.code, "SNAPBACK_HANDLER_FAILED");
        assert!(
            undeclared.diagnostic.details.get("appCode").is_none(),
            "an undeclared code never reaches the caller"
        );
        assert!(
            !serde_json::to_string(&undeclared.diagnostic.details)
                .expect("details serialize")
                .contains("hidden"),
            "an undeclared refusal's payload is dropped"
        );

        snapback
            .telemetry
            .force_flush()
            .expect("flush refusal emission evidence");
        let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
            &database_path,
        ))
        .expect("open refusal telemetry sibling");
        let details_for = |name: &str| -> Value {
            let encoded: String = raw
                .query_row(
                    "SELECT details FROM telemetry_events_visible WHERE kind='function_run' AND name=?1 ORDER BY id DESC LIMIT 1",
                    rusqlite::params![name],
                    |row| row.get(0),
                )
                .expect("function failure details");
            serde_json::from_str(&encoded).expect("failure details decode")
        };
        let tracked_details = details_for("declaredRefusal");
        assert_eq!(tracked_details["failure_disposition"], "app_refusal");
        assert_eq!(tracked_details["issue_eligible"], true);
        assert_eq!(tracked_details["fp_branch"], "app_refusal");
        assert!(tracked_details["fp_hash"].as_str().is_some());
        let untracked_details = details_for("untrackedRefusal");
        assert_eq!(untracked_details["failure_disposition"], "app_refusal");
        assert_eq!(untracked_details["issue_eligible"], false);
        assert!(untracked_details.get("fp_hash").is_none());
        let grouped_names = raw
            .prepare("SELECT name FROM error_groups_visible ORDER BY name")
            .unwrap()
            .query_map([], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(
            grouped_names,
            vec!["declaredRefusal".to_owned(), "undeclaredRefusal".to_owned()],
            "tracked admission and folded exception group; admitted-untracked refusal does not",
        );
    }

    const ASSET_CALLBACK_SOURCE: &str = r#"
globalThis.__snapbackHandlers = {
  async onAssetReady(ctx, args) {
    await ctx.db.insert('callback_log', { event: args.event, assetId: args.assetId });
    return null;
  },
  async onAssetBoom() {
    throw new Error('callback boom');
  }
};
"#;

    /// Two callback-declaring intents (a working handler and a throwing
    /// one) plus a log table the working callback writes.
    fn asset_callback_snapback() -> LocalSnapback {
        let mut snapback = LocalSnapback::memory().expect("memory snapback");
        let callback_policy = |ready: &str| crate::manifest::AssetCallbackPolicy {
            ready: Some(ready.to_owned()),
            rejected: None,
        };
        let mut ready_intent = asset_test_intent();
        ready_intent.on = Some(callback_policy("onAssetReady"));
        let mut boom_intent = asset_profile_intent(
            "boomUpload",
            crate::assets::AssetDeliveryProfile::PrivateStrict,
        );
        boom_intent.on = Some(callback_policy("onAssetBoom"));
        let callback_fn = |name: &str| {
            FunctionDefinition::new(
                name,
                FunctionKind::Mutation,
                FunctionRuntime::IbexModule(IbexModule {
                    source: ASSET_CALLBACK_SOURCE.to_owned(),
                    export: name.to_owned(),
                }),
            )
        };
        let diagnostics = snapback.load_functions(FunctionManifest {
            functions: vec![callback_fn("onAssetReady"), callback_fn("onAssetBoom")],
            asset_upload_intents: vec![ready_intent, boom_intent],
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "callback manifest must load: {diagnostics:?}"
        );
        let log_table = crate::manifest::TableManifest {
            name: "callback_log".to_owned(),
            fields: vec![
                crate::manifest::FieldManifest {
                    name: "event".to_owned(),
                    field_type: crate::manifest::FieldType::String,
                    optional: true,
                },
                crate::manifest::FieldManifest {
                    name: "assetId".to_owned(),
                    field_type: crate::manifest::FieldType::String,
                    optional: true,
                },
            ],
            indexes: Vec::new(),
            syncable: false,
            permission_backing: false,
            permission_fields: None,
            search_indexes: Vec::new(),
            vector_indexes: Vec::new(),
            search_live_limits: None,
            membership: None,
            asset_sharing: None,
            history: None,
        };
        snapback
            .db
            .apply_schema(SchemaManifest {
                tables: vec![log_table],
                ..SchemaManifest::default()
            })
            .expect("schema");
        snapback
    }

    fn asset_callback_log_count(snapback: &mut LocalSnapback) -> u64 {
        snapback
            .db
            .asset_transaction(|tx| {
                Ok(
                    tx.query_row("SELECT COUNT(*) FROM callback_log", [], |row| {
                        row.get::<_, u64>(0)
                    })?,
                )
            })
            .expect("count")
    }

    #[test]
    fn asset_lifecycle_callback_invokes_idempotently_and_isolates_failure() {
        let mut snapback = asset_callback_snapback();
        let now = now_millis();

        // Ready enqueues the callback transactionally with the transition.
        let asset_id = asset_ready(&mut snapback, "user_a", b"callback-bytes");
        let rows = snapback
            .db
            .asset_transaction(|tx| crate::assets::work_rows_for_asset(tx, &asset_id))
            .expect("rows");
        let callback_rows: Vec<_> = rows
            .iter()
            .filter(|row| row.kind == crate::assets::ASSET_WORK_KIND_LIFECYCLE_CALLBACK)
            .collect();
        assert_eq!(
            callback_rows.len(),
            1,
            "ready enqueued exactly one callback"
        );

        // The runner invokes the declared mutation with typed facts.
        snapback.asset_runner_tick(now_millis() + 1).expect("tick");
        assert_eq!(asset_callback_log_count(&mut snapback), 1);
        let generation = callback_rows[0].lifecycle_generation;

        // A re-driven duplicate never doubles the observable effect: the
        // stable idempotency key rides the client-mutation ledger.
        snapback
            .db
            .asset_transaction(|tx| {
                crate::assets::enqueue_work_with_params(
                    tx,
                    crate::assets::ASSET_WORK_KIND_LIFECYCLE_CALLBACK,
                    &asset_id,
                    None,
                    generation,
                    now + 2,
                    Some(serde_json::json!({
                        "event": "ready",
                        "handler": "onAssetReady",
                    })),
                )
                .map(|_| ())
            })
            .expect("duplicate enqueues");
        snapback.asset_runner_tick(now_millis() + 1).expect("tick");
        assert_eq!(
            asset_callback_log_count(&mut snapback),
            1,
            "replayed callback must not double its observable effect"
        );

        // A throwing callback retries toward its ceiling and never touches
        // the asset: failure is isolated to the work row.
        let boom_asset =
            asset_ready_under_intent(&mut snapback, "user_a", b"boom-bytes", "boomUpload");
        snapback.asset_runner_tick(now_millis() + 1).expect("tick");
        let boom_rows = snapback
            .db
            .asset_transaction(|tx| crate::assets::work_rows_for_asset(tx, &boom_asset))
            .expect("rows");
        let boom_row = boom_rows
            .iter()
            .find(|row| row.kind == crate::assets::ASSET_WORK_KIND_LIFECYCLE_CALLBACK)
            .expect("boom callback row");
        assert!(boom_row.attempt_count >= 1, "failure counted an attempt");
        assert!(matches!(
            boom_row.state,
            crate::assets::AssetWorkState::Enqueued
                | crate::assets::AssetWorkState::Retrying
                | crate::assets::AssetWorkState::Exhausted
        ));
        let boom = snapback
            .db
            .asset_transaction(|tx| crate::assets::load_asset(tx, &boom_asset))
            .expect("load")
            .expect("asset");
        assert_eq!(
            boom.availability,
            crate::assets::AssetAvailability::Ready,
            "callback failure never degrades the asset"
        );
        assert_eq!(asset_callback_log_count(&mut snapback), 1);
    }

    #[test]
    fn asset_reference_gc_disabled_schema_never_reclaims() {
        let mut snapback = asset_reference_snapback();
        let unattached = asset_ready(&mut snapback, "user_a", b"never-attached");
        let report = snapback
            .asset_gc_sweep(now_millis() + crate::assets::ASSET_REFERENCE_GC_GRACE_MAX_MS * 2)
            .expect("sweep");
        assert_eq!(report.reference_reclaimed, 0, "opt-in means opt-in");
        let asset = snapback
            .db
            .asset_transaction(|tx| crate::assets::load_asset(tx, &unattached))
            .expect("load")
            .expect("asset survives");
        assert_eq!(asset.availability, crate::assets::AssetAvailability::Ready);
    }

    #[test]
    fn asset_handler_raw_write_refuses_and_attach_admission_commits_edge() {
        let mut snapback = asset_reference_snapback();
        let asset_id = asset_ready(&mut snapback, "user_a", b"avatar-bytes");
        let insert = |id: &str, asset: &str| crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: id.to_owned(),
            values: serde_json::Map::from_iter([
                ("title".to_owned(), json!("hello")),
                ("photo".to_owned(), json!(asset)),
            ]),
        };
        // A raw id-shaped string with no admission fails the commit: the
        // hook is the authority, not the helper.
        let error = asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![insert("post_raw", &asset_id)],
            Vec::new(),
        )
        .expect_err("raw write refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_REF_UNVERIFIED");
        // The same write under a ctx.assets.attach admission commits the row
        // and its reverse edge in one changeset.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![insert("post_ok", &asset_id)],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: Some("avatarUpload".to_owned()),
            }],
        )
        .expect("admitted write commits");
        let edges = asset_edges(&mut snapback, "posts", "post_ok");
        assert_eq!(edges.len(), 1);
        assert_eq!(edges[0].asset_id, asset_id);
        assert!(
            asset_receipt_events(&mut snapback, &asset_id)
                .contains(&"attachment-committed".to_owned())
        );
    }

    #[test]
    fn asset_attach_wrong_intent_wrong_owner_and_deleted_asset_fail_closed() {
        let mut snapback = asset_reference_snapback();
        let asset_id = asset_ready(&mut snapback, "user_a", b"strict-bytes");
        let insert = crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: "post_x".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), json!(asset_id))]),
        };
        // Intent disagreement between the admission and the field restriction.
        let error = asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![insert.clone()],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: Some("someOtherIntent".to_owned()),
            }],
        )
        .expect_err("intent mismatch refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_ASSET_ATTACH_INTENT_MISMATCH"
        );
        // A different caller cannot attach another owner's asset.
        let error = asset_handler_commit(
            &mut snapback,
            "user_b",
            vec![insert.clone()],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: None,
            }],
        )
        .expect_err("foreign owner refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
        // The attach-versus-delete race: the admission was recorded, the
        // asset is deleted before commit, and the commit-time re-check
        // refuses instead of committing a stale admission.
        snapback
            .db
            .asset_transaction(|tx| {
                let mut asset = crate::assets::load_asset(tx, &asset_id)?.unwrap();
                crate::assets::transition_asset(
                    tx,
                    &mut asset,
                    crate::assets::AssetAvailability::Deleted,
                    now_millis(),
                )
            })
            .expect("asset deleted");
        let error = asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![insert],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: None,
            }],
        )
        .expect_err("deleted asset refuses at commit");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_ATTACH_UNAVAILABLE");
    }

    #[test]
    fn asset_host_plan_and_seed_derive_admission_from_the_restriction() {
        let mut snapback = asset_reference_snapback();
        let asset_id = asset_ready(&mut snapback, "user_a", b"plan-bytes");
        let plan_insert = |table: &str, field: &str, asset: &str| MutationPlan {
            steps: vec![MutationStep::Insert {
                table: table.to_owned(),
                values: BTreeMap::from([(field.to_owned(), ValueExpr::Literal(json!(asset)))]),
                bind_id_as: None,
            }],
            return_value: None,
        };
        let input_for = |user: &str| HandlerInput {
            auth: crate::manifest::AuthInput {
                user_id: Some(user.to_owned()),
                ..Default::default()
            },
            ..Default::default()
        };
        // Restricted field: the commit boundary derives the full admission.
        snapback
            .db
            .execute_mutation(
                &plan_insert("posts", "photo", &asset_id),
                &input_for("user_a"),
            )
            .expect("host plan with restriction commits");
        // Wrong owner fails closed.
        let error = snapback
            .db
            .execute_mutation(
                &plan_insert("posts", "photo", &asset_id),
                &input_for("user_b"),
            )
            .expect_err("foreign host plan refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
        // A restriction-less field is handler-attach-only on host plans.
        let error = snapback
            .db
            .execute_mutation(
                &plan_insert("drafts", "pic", &asset_id),
                &input_for("user_a"),
            )
            .expect_err("unrestricted host plan refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_REF_UNVERIFIED");
        // Seeds run the same commit-boundary admission under system
        // authority: the restricted field admits, the unrestricted refuses.
        snapback
            .db
            .seed(SeedData {
                tables: BTreeMap::from([(
                    "posts".to_owned(),
                    vec![serde_json::Map::from_iter([
                        ("title".to_owned(), json!("seeded")),
                        ("photo".to_owned(), json!(asset_id)),
                    ])],
                )]),
            })
            .expect("seed with restriction commits");
        let error = snapback
            .db
            .seed(SeedData {
                tables: BTreeMap::from([(
                    "drafts".to_owned(),
                    vec![serde_json::Map::from_iter([(
                        "pic".to_owned(),
                        json!(asset_id),
                    )])],
                )]),
            })
            .expect_err("unrestricted seed refuses");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_REF_UNVERIFIED");
    }

    #[test]
    fn asset_edges_follow_patch_clear_and_row_delete_in_the_same_changeset() {
        let mut snapback = asset_reference_snapback();
        let first = asset_ready(&mut snapback, "user_a", b"first-bytes");
        let second = asset_ready(&mut snapback, "user_a", b"second-bytes");
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "posts".to_owned(),
                id: "post_e".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(first))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: first.clone(),
                upload: None,
            }],
        )
        .expect("insert attaches");
        // Change: the old edge is removed and the new one committed together.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Patch {
                table: "posts".to_owned(),
                id: "post_e".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(second))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: second.clone(),
                upload: None,
            }],
        )
        .expect("patch re-attaches");
        let edges = asset_edges(&mut snapback, "posts", "post_e");
        assert_eq!(edges.len(), 1);
        assert_eq!(edges[0].asset_id, second);
        assert!(
            asset_receipt_events(&mut snapback, &first).contains(&"reference-removed".to_owned())
        );
        // Clear: writing null removes the edge with no new admission needed.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Patch {
                table: "posts".to_owned(),
                id: "post_e".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), Value::Null)]),
            }],
            Vec::new(),
        )
        .expect("clear commits");
        assert!(asset_edges(&mut snapback, "posts", "post_e").is_empty());
        // Row delete removes every edge for the row.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "posts".to_owned(),
                id: "post_f".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(second))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: second.clone(),
                upload: None,
            }],
        )
        .expect("insert attaches");
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Delete {
                table: "posts".to_owned(),
                id: "post_f".to_owned(),
            }],
            Vec::new(),
        )
        .expect("delete commits");
        assert!(asset_edges(&mut snapback, "posts", "post_f").is_empty());
    }

    fn asset_shared_intent() -> crate::manifest::AssetUploadIntentDefinition {
        let mut intent = asset_test_intent();
        intent.access = crate::manifest::AssetAccessPolicy {
            read: crate::assets::AssetReadAccessPolicy::ViaReferences,
        };
        intent
    }

    #[test]
    fn asset_read_authorization_decides_only_through_sharing_declarations() {
        let mut snapback = asset_reference_snapback();
        snapback.load_functions(FunctionManifest {
            asset_upload_intents: vec![asset_shared_intent()],
            ..FunctionManifest::default()
        });
        let asset_id = asset_ready(&mut snapback, "user_a", b"shared-bytes");
        let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
        let outsider = asset_dev_authority(&snapback, "user_b", InvocationSource::HttpQuery);
        // Unreferenced: readable only by its owner, even under via-references.
        snapback
            .asset_record_inspect(&owner, &asset_id)
            .expect("owner reads");
        let error = snapback
            .asset_record_inspect(&outsider, &asset_id)
            .expect_err("unreferenced asset denies the outsider");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
        // A reference on the mixed-table stand-in (no sharing declaration)
        // confers nothing, however visible its rows may otherwise be.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "drafts".to_owned(),
                id: "draft_1".to_owned(),
                values: serde_json::Map::from_iter([("pic".to_owned(), json!(asset_id))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: None,
            }],
        )
        .expect("handler attach into the undeclared table commits");
        let error = snapback
            .asset_record_inspect(&outsider, &asset_id)
            .expect_err("no sharing declaration = no bypass");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
        // A public-read-shared reference grants with the edge commit and
        // revokes with its removal.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "posts".to_owned(),
                id: "post_s".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(asset_id))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: None,
            }],
        )
        .expect("shared attach commits");
        snapback
            .asset_record_inspect(&outsider, &asset_id)
            .expect("grant arrives with the edge commit");
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Delete {
                table: "posts".to_owned(),
                id: "post_s".to_owned(),
            }],
            Vec::new(),
        )
        .expect("detach commits");
        let error = snapback
            .asset_record_inspect(&outsider, &asset_id)
            .expect_err("revoke arrives with the edge removal");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
        // Owner-field sharing admits exactly the row's owner-field principal.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "owned".to_owned(),
                id: "owned_1".to_owned(),
                values: serde_json::Map::from_iter([
                    ("ownerId".to_owned(), json!("user_b")),
                    ("photo".to_owned(), json!(asset_id)),
                ]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: None,
            }],
        )
        .expect("owner-field attach commits");
        snapback
            .asset_record_inspect(&outsider, &asset_id)
            .expect("the owner-field principal reads");
        let stranger = asset_dev_authority(&snapback, "user_c", InvocationSource::HttpQuery);
        let error = snapback
            .asset_record_inspect(&stranger, &asset_id)
            .expect_err("a third principal stays denied");
        assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
    }

    #[test]
    fn asset_read_decision_pins_the_empty_edge_range_so_first_attachment_moves_it() {
        let mut snapback = asset_reference_snapback();
        snapback.load_functions(FunctionManifest {
            asset_upload_intents: vec![asset_shared_intent()],
            ..FunctionManifest::default()
        });
        let asset_id = asset_ready(&mut snapback, "user_a", b"wake-bytes");
        let schema = snapback.db.schema().clone();
        let captured = snapback
            .db
            .asset_transaction(|tx| {
                let asset = crate::assets::load_asset(tx, &asset_id)?.unwrap();
                let decision =
                    crate::storage::asset_read_authorized(&schema, tx, Some("user_b"), &asset)?;
                assert!(!decision.authorized);
                Ok(decision.dependencies)
            })
            .expect("decision");
        // The empty reverse-edge range is a first-class captured dependency.
        assert!(captured.iter().any(|dependency| {
            dependency.result_count == Some(0)
                && dependency.table.as_deref() == Some("_snapback_asset_reference_edges_v1")
        }));
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "posts".to_owned(),
                id: "post_w".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(asset_id))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: None,
            }],
        )
        .expect("first attachment commits");
        let schema = snapback.db.schema().clone();
        let moved = snapback
            .db
            .asset_transaction(|tx| {
                let asset = crate::assets::load_asset(tx, &asset_id)?.unwrap();
                crate::storage::asset_read_dependencies_moved(
                    &schema,
                    tx,
                    Some("user_b"),
                    &asset,
                    &captured,
                )
            })
            .expect("re-evaluation");
        assert!(
            moved,
            "the first attachment must move the pinned empty capture"
        );
    }

    fn asset_live_input(connection_id: &str, user: &str, asset_id: &str) -> LiveSubscribeInput {
        LiveSubscribeInput {
            connection_id: connection_id.to_owned(),
            input: HandlerInput {
                args: json!({ "assetId": asset_id }),
                auth: crate::manifest::AuthInput {
                    user_id: Some(user.to_owned()),
                    ..crate::manifest::AuthInput::default()
                },
                ..HandlerInput::default()
            },
            authorization_namespace: None,
            supersedes: None,
            resume_from_token: None,
        }
    }

    fn asset_last_replace_rows(snapback: &mut LocalSnapback, connection_id: &str) -> Vec<Value> {
        let frames = rqs_drained_envelopes(snapback, connection_id);
        let replace = frames
            .iter()
            .rev()
            .find(|frame| frame["kind"] == "live_replace")
            .unwrap_or_else(|| panic!("no live_replace frame for {connection_id}: {frames:?}"));
        replace["rows"].as_array().cloned().unwrap_or_default()
    }

    #[test]
    fn asset_record_live_projection_publishes_wakes_and_blanks_with_no_polling() {
        let mut snapback = asset_reference_snapback();
        snapback.load_functions(FunctionManifest {
            asset_upload_intents: vec![asset_shared_intent()],
            ..FunctionManifest::default()
        });
        // The owner subscribes to a pending asset and holds the pending row.
        let created = asset_upload(&mut snapback, "user_a", b"live-bytes", true);
        let asset_id = created.task.asset_id.clone();
        let attempt_id = created.task.attempt_id.clone();
        let established = snapback
            .subscribe_live(
                ASSET_RECORD_LIVE_FUNCTION,
                asset_live_input("conn-owner", "user_a", &asset_id),
            )
            .expect("owner subscribes to the reserved projection");
        let snapshot = established.snapshot.expect("initial rows");
        assert_eq!(snapshot.rows.len(), 1);
        assert_eq!(snapshot.rows[0]["availability"], "pending");
        assert!(established.resume.is_none(), "never RQS-eligible");

        // Publish: the durable transition reaches the subscriber with no
        // polling — the finalize itself fans out the frame.
        asset_finalize(&mut snapback, "user_a", &attempt_id, None).expect("publishes");
        let rows = asset_last_replace_rows(&mut snapback, "conn-owner");
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0]["availability"], "ready");

        // An outsider's subscription establishes blank (owner-only through
        // no edge), then the FIRST attachment wakes it — the pinned
        // empty-range capture moving through an ordinary app commit.
        let outsider = snapback
            .subscribe_live(
                ASSET_RECORD_LIVE_FUNCTION,
                asset_live_input("conn-b", "user_b", &asset_id),
            )
            .expect("outsider subscribes");
        assert_eq!(
            outsider.snapshot.expect("blank rows").rows.len(),
            0,
            "unreferenced assets blank for non-owners"
        );
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "posts".to_owned(),
                id: "post_live".to_owned(),
                values: serde_json::Map::from_iter([("photo".to_owned(), json!(asset_id))]),
            }],
            vec![crate::assets::AssetAttachmentAdmission {
                asset_id: asset_id.clone(),
                upload: None,
            }],
        )
        .expect("first attachment commits");
        let rows = asset_last_replace_rows(&mut snapback, "conn-b");
        assert_eq!(rows.len(), 1, "the attachment wakes the blank subscriber");
        assert_eq!(rows[0]["availability"], "ready");

        // Revocation: removing the referencing row blanks the outsider at
        // the governed boundary, while the owner's view stays intact.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Delete {
                table: "posts".to_owned(),
                id: "post_live".to_owned(),
            }],
            Vec::new(),
        )
        .expect("detach commits");
        let rows = asset_last_replace_rows(&mut snapback, "conn-b");
        assert_eq!(rows.len(), 0, "edge removal blanks the live view");

        // Deletion blanks the owner too.
        let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
        snapback.asset_delete(&owner, &asset_id).expect("delete");
        let rows = asset_last_replace_rows(&mut snapback, "conn-owner");
        assert_eq!(rows.len(), 0, "deletion blanks the record projection");
    }

    /// LLP 0100 receipt witness: the removed member's `_snapback.myMemberships`
    /// subscription drops the seat at the same authorization cut the
    /// principal-addressed removal commits — the product-visible coherence of
    /// one cut (0056's machinery, driven here by the NEW addressing mode
    /// end to end through an authored JS mutation), while the absent-target
    /// no-op delivers nothing.
    #[test]
    fn remove_principal_drops_the_seat_from_my_memberships_at_the_cut() {
        let mut snapback = my_memberships_snapback_with_removal();
        seed_membership_row(&mut snapback, "seat_owner", "chan1", "user_a", "owner");
        seed_membership_row(&mut snapback, "seat_b", "chan1", "user_b", "member");
        // Advance the storage head past the seeded row versions so the
        // membership planners' managed-version validation sees a
        // committed-history-consistent table.
        asset_handler_commit(
            &mut snapback,
            "user_a",
            vec![crate::storage::BufferedWrite::Insert {
                table: "notes".to_owned(),
                id: "note_seed".to_owned(),
                values: serde_json::Map::from_iter([("body".to_owned(), json!("advance head"))]),
            }],
            Vec::new(),
        )
        .expect("head-advancing commit");

        let b = snapback
            .subscribe_live(
                MY_MEMBERSHIPS_LIVE_FUNCTION,
                memberships_live_input("conn-b", Some("user_b")),
            )
            .expect("target subscribes");
        assert_eq!(b.snapshot.expect("rows").rows.len(), 1, "one seat before");

        // The owner removes user_b through the principal-addressed command.
        let output = snapback
            .invoke_mutation(
                "ownerRemove",
                HandlerInput {
                    args: json!({ "channelId": "chan1", "principal": "user_b" }),
                    auth: crate::manifest::AuthInput {
                        user_id: Some("user_a".to_owned()),
                        principal: Some("user_a".to_owned()),
                        ..crate::manifest::AuthInput::default()
                    },
                    ..HandlerInput::default()
                },
            )
            .expect("owner removes member");
        assert_eq!(output.result, Value::Null, "the public result is null");

        let rows = asset_last_replace_rows(&mut snapback, "conn-b");
        assert_eq!(
            rows.len(),
            0,
            "the seat drops from myMemberships at the removal cut"
        );

        // The absent-target no-op delivers nothing further to the target.
        snapback
            .invoke_mutation(
                "ownerRemove",
                HandlerInput {
                    args: json!({ "channelId": "chan1", "principal": "user_b" }),
                    auth: crate::manifest::AuthInput {
                        user_id: Some("user_a".to_owned()),
                        principal: Some("user_a".to_owned()),
                        ..crate::manifest::AuthInput::default()
                    },
                    ..HandlerInput::default()
                },
            )
            .expect("absent-target no-op");
        let frames = rqs_drained_envelopes(&mut snapback, "conn-b");
        assert!(
            frames.iter().all(|frame| frame["kind"] != "live_replace"),
            "the no-op delivers no seat change: {frames:?}"
        );
    }

    /// The myMemberships fixture plus the LLP 0100 opt-in and an authored
    /// removal mutation over the real ctx.membership bridge.
    fn my_memberships_snapback_with_removal() -> LocalSnapback {
        let mut snapback = my_memberships_snapback();
        let schema_patch = {
            let mut schema = snapback.db.schema().clone();
            let membership = schema
                .tables
                .iter_mut()
                .find(|table| table.name == "channel_members")
                .and_then(|table| table.membership.as_mut())
                .expect("membership declaration");
            membership
                .transitions
                .push(crate::manifest::MembershipTransition {
                    op: crate::manifest::MembershipOp::Remove,
                    by: vec!["owner".to_owned()],
                    target: crate::manifest::MembershipTarget::Other,
                    from: None,
                    to: None,
                    fields: None,
                });
            membership.principal_addressed_writes =
                Some(crate::manifest::MembershipPrincipalAddressedWrites { remove: true });
            schema
        };
        snapback
            .db
            .apply_schema(schema_patch)
            .expect("apply removal opt-in");
        let mut function = FunctionDefinition::new(
            "ownerRemove",
            FunctionKind::Mutation,
            FunctionRuntime::IbexModule(IbexModule {
                source: "globalThis.__snapbackHandlers = {\
                     async ownerRemove(ctx, args) {\
                       return await ctx.membership.channelSeats.removePrincipal(\
                         args.channelId, args.principal);\
                     } };"
                    .to_owned(),
                export: "ownerRemove".to_owned(),
            }),
        );
        function.auth_requirement = Some(crate::manifest::AuthRequirement::Authenticated);
        let diagnostics = snapback.load_functions(FunctionManifest {
            functions: vec![function],
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics
                .iter()
                .all(|diagnostic| diagnostic.severity
                    != crate::diagnostic::DiagnosticSeverity::Error),
            "removal fixture must install: {diagnostics:?}"
        );
        snapback
    }

