    #[test]
    fn config_verify_admission_precedes_cooldown_and_retirement_suppresses_finish() {
        let mut snapback = config_verify_gate_snapback();
        let guard = snapback.admission.begin_transition().unwrap();
        let Err(error) = snapback.stage_config_verify("gateKey") else {
            panic!("closed config verification must fail before staging");
        };
        assert_eq!(error.diagnostic.code, "SNAPBACK_AUTH_MODE_PENDING");
        drop(guard);

        let stage = match snapback
            .stage_config_verify("gateKey")
            .expect("closed attempt did not claim cooldown")
        {
            super::StagedConfigVerify::Ready(stage) => stage,
            super::StagedConfigVerify::Done(_) => panic!("valid probe must stage"),
        };
        let admission = stage.admission.clone();
        let revision = stage.entry_revision;
        let started = stage.started_ms;
        drop(stage);
        let diagnostics_before = snapback.recent_diagnostics.len();
        assert!(snapback.config.entry("gateKey").unwrap().verified.is_none());
        let controller = snapback.admission.clone();
        BEFORE_CONFIG_VERIFY_PUBLICATION_HOOK.with(|slot| {
            *slot.borrow_mut() = Some(Box::new(move || {
                assert_eq!(
                    controller
                        .retire_current_epoch_for_test()
                        .unwrap_err()
                        .diagnostic
                        .code,
                    "SNAPBACK_AUTH_MODE_QUIESCENCE_TIMEOUT"
                );
            }));
        });
        assert_eq!(
            snapback
                .finish_config_verify(
                    "gateKey",
                    revision,
                    started,
                    Ok(json!({ "ok": true })),
                    admission,
                )
                .unwrap_err()
                .diagnostic
                .code,
            "SNAPBACK_AUTH_MODE_PENDING"
        );
        assert!(snapback.config.entry("gateKey").unwrap().verified.is_none());
        assert_eq!(snapback.recent_diagnostics.len(), diagnostics_before);
    }

    #[test]
    fn legacy_local_and_read_lane_apis_reject_settled_sessions_mode() {
        let mut snapback = LocalSnapback::memory().expect("memory snapback");
        snapback
            .synchronize_auth_mode_admission(&settled_sessions_state())
            .expect("publish exact Sessions mode");

        let assert_mode_rejection = |error: crate::diagnostic::SnapbackError| {
            assert_eq!(error.diagnostic.code, "SNAPBACK_AUTH_POLICY_UNAVAILABLE");
        };
        assert_mode_rejection(
            snapback
                .invoke_query("missing", HandlerInput::default())
                .unwrap_err(),
        );
        assert_mode_rejection(
            snapback
                .invoke_mutation("missing", HandlerInput::default())
                .unwrap_err(),
        );
        assert_mode_rejection(
            snapback
                .dry_run_mutation("missing", HandlerInput::default())
                .unwrap_err(),
        );
        assert_eq!(
            snapback
                .run_function("missing", HandlerInput::default())
                .diagnostic
                .expect("runner rejection")
                .code,
            "SNAPBACK_AUTH_POLICY_UNAVAILABLE"
        );
        assert_eq!(
            snapback
                .run_app_action("missing", HandlerInput::default())
                .diagnostic
                .expect("action rejection")
                .code,
            "SNAPBACK_AUTH_POLICY_UNAVAILABLE"
        );
        assert_mode_rejection(
            snapback
                .read_lane()
                .invoke_query("missing", HandlerInput::default())
                .unwrap_err(),
        );
    }

    #[test]
    fn authority_generation_counters_refuse_before_wrap_or_reuse() {
        let counter = AtomicU64::new(u64::MAX - 1);
        assert_eq!(reserve_unique_generation(&counter).unwrap(), u64::MAX - 1);
        assert_eq!(counter.load(Ordering::Relaxed), u64::MAX);
        assert_eq!(
            reserve_unique_generation(&counter)
                .unwrap_err()
                .diagnostic
                .code,
            "SNAPBACK_APP_GENERATION_EXHAUSTED"
        );
        assert_eq!(counter.load(Ordering::Relaxed), u64::MAX);
        assert_eq!(
            next_secret_read_reset_generation(u64::MAX)
                .unwrap_err()
                .diagnostic
                .code,
            "SNAPBACK_ADMIN_SECRET_READ_GENERATION_EXHAUSTED"
        );
    }

    fn reload_schema(hash: &str, include_extra: bool) -> SchemaManifest {
        let fields = vec![FieldManifest {
            name: "value".to_owned(),
            field_type: FieldType::String,
            optional: false,
        }];
        let mut tables = vec![TableManifest {
            name: "items".to_owned(),
            fields,
            indexes: Vec::new(),
            syncable: true,
            permission_backing: false,
            permission_fields: None,
            search_indexes: Vec::new(),
            vector_indexes: Vec::new(),
            search_live_limits: None,
            membership: None,
            asset_sharing: None,
            history: None,
        }];
        if include_extra {
            tables.push(TableManifest {
                name: "new_items".to_owned(),
                fields: vec![FieldManifest {
                    name: "extra".to_owned(),
                    field_type: FieldType::Boolean,
                    optional: true,
                }],
                indexes: Vec::new(),
                syncable: true,
                permission_backing: false,
                permission_fields: None,
                search_indexes: Vec::new(),
                vector_indexes: Vec::new(),
                search_live_limits: None,
                membership: None,
                asset_sharing: None,
                history: None,
            });
        }
        SchemaManifest {
            schema_hash: Some(hash.to_owned()),
            tables,
            ..SchemaManifest::default()
        }
    }

    fn reload_functions() -> FunctionManifest {
        let define = |name: &str| {
            FunctionDefinition::new(
                name,
                FunctionKind::Mutation,
                FunctionRuntime::IbexModule(IbexModule {
                    source: SCHEMA_RELOAD_SOURCE.to_owned(),
                    export: name.to_owned(),
                }),
            )
        };
        FunctionManifest {
            functions: vec![define("insertOld"), define("readNewTable")],
            ..FunctionManifest::default()
        }
    }

    fn guarded_functions() -> FunctionManifest {
        let mut values = BTreeMap::new();
        values.insert("value".to_owned(), ValueExpr::Literal(json!("guarded")));
        FunctionManifest {
            functions: vec![
                FunctionDefinition::new(
                    "hostInsert",
                    FunctionKind::Mutation,
                    FunctionRuntime::HostPlan(HandlerPlan::Mutation(MutationPlan {
                        steps: vec![MutationStep::Insert {
                            table: "items".to_owned(),
                            values,
                            bind_id_as: None,
                        }],
                        return_value: Some(ReturnValue::ChangedCount),
                    })),
                ),
                FunctionDefinition::new(
                    "ibexInsert",
                    FunctionKind::Mutation,
                    FunctionRuntime::IbexModule(IbexModule {
                        source: "globalThis.__snapbackHandlers = { async ibexInsert() { return null; } };"
                            .to_owned(),
                        export: "ibexInsert".to_owned(),
                    }),
                ),
            ],
            ..FunctionManifest::default()
        }
    }

    fn guarded_snapback() -> LocalSnapback {
        let mut snapback = LocalSnapback::memory().expect("memory snapback");
        snapback
            .apply_schema(reload_schema("guarded-schema", false))
            .expect("apply guarded schema");
        snapback.load_functions(guarded_functions());
        snapback
    }

    #[test]
    fn served_staging_and_managed_action_emit_function_and_runtime_log_observations() {
        fn stage_and_commit(
            snapback: &mut LocalSnapback,
            database_path: &std::path::Path,
            name: &str,
            input: HandlerInput,
        ) {
            let correlation =
                telemetry_correlation(&input.correlation).expect("staged observation correlation");
            let authority = InvocationGate::prepare_dev_input(
                InvocationSource::LocalMutation,
                ServerProfile::Test,
                &input,
            )
            .expect("prepare staged mutation authority");
            let (preflight, staged) = snapback
                .stage_recorded_authorization_mutation(
                    name,
                    input,
                    None,
                    None,
                    &[],
                    "test",
                    authority,
                )
                .expect("stage served mutation");
            snapback
                .telemetry
                .force_flush()
                .expect("flush staged observations");
            let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
                database_path,
            ))
            .expect("open staged telemetry sibling");
            let staged_successes: i64 = raw
                .query_row(
                    "SELECT COUNT(*) FROM telemetry_events WHERE kind='function_run' AND name=?1 AND phase='joined' AND status=200 AND correlation=?2",
                    rusqlite::params![name, correlation],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(
                staged_successes, 0,
                "staging cannot publish a successful terminal observation"
            );
            drop(raw);
            let (result, _receipt) = snapback
                .try_with_direct_authorization_write(preflight, move |snapback| {
                    snapback.commit_staged_recorded_authorization_mutation(staged)
                })
                .expect("reserve staged mutation")
                .expect("record staged mutation");
            result.expect("commit staged mutation");
        }

        let directory = tempfile::tempdir().expect("function telemetry fixture directory");
        let database_path = directory.path().join("function-telemetry.sqlite3");
        let mut snapback =
            LocalSnapback::open(&database_path).expect("file-backed function fixture");
        snapback
            .apply_schema(reload_schema("function-telemetry", false))
            .expect("apply function telemetry schema");
        let mut manifest = guarded_functions();
        let ibex = manifest
            .functions
            .iter_mut()
            .find(|function| function.name == "ibexInsert")
            .expect("Ibex fixture function");
        ibex.runtime = FunctionRuntime::IbexModule(IbexModule {
            source: "globalThis.__snapbackHandlers = { async ibexInsert() { console.log('staged-log'); return null; } };"
                .to_owned(),
            export: "ibexInsert".to_owned(),
        });
        manifest.functions.push(FunctionDefinition::new(
            "emptyAction",
            FunctionKind::Action,
            FunctionRuntime::HostPlan(HandlerPlan::Action(ActionPlan {
                steps: Vec::new(),
                return_value: None,
            })),
        ));
        let diagnostics = snapback.load_functions(manifest);
        assert!(
            diagnostics
                .iter()
                .all(|diagnostic| diagnostic.severity
                    != crate::diagnostic::DiagnosticSeverity::Error),
            "telemetry fixture must load: {diagnostics:?}"
        );

        let with_correlation = |correlation: &str| HandlerInput {
            correlation: Some(json!(correlation)),
            ..input()
        };
        stage_and_commit(
            &mut snapback,
            &database_path,
            "hostInsert",
            with_correlation("host-staged"),
        );
        stage_and_commit(
            &mut snapback,
            &database_path,
            "ibexInsert",
            with_correlation("ibex-staged"),
        );

        let refused_input = with_correlation("host-refused");
        let refused_authority = InvocationGate::prepare_dev_input(
            InvocationSource::LocalMutation,
            ServerProfile::Test,
            &refused_input,
        )
        .expect("prepare refused staged mutation authority");
        let (refused_preflight, mut refused_staged) = snapback
            .stage_recorded_authorization_mutation(
                "hostInsert",
                refused_input,
                None,
                None,
                &[],
                "test",
                refused_authority,
            )
            .expect("stage mutation before authoritative refusal");
        match &mut refused_staged {
            StagedRecordedMutation::Ready(staged) => {
                staged.execution = StagedMutationExecution::HostPlan(MutationPlan {
                    steps: vec![MutationStep::Insert {
                        table: "missing_after_stage".to_owned(),
                        values: BTreeMap::new(),
                        bind_id_as: None,
                    }],
                    return_value: Some(ReturnValue::ChangedCount),
                });
            }
            StagedRecordedMutation::Done(_) => panic!("fresh refusal fixture must stage"),
        }
        let (refused, _receipt) = snapback
            .try_with_direct_authorization_write(refused_preflight, move |snapback| {
                snapback.commit_staged_recorded_authorization_mutation(refused_staged)
            })
            .expect("reserve refused mutation")
            .expect("record refused mutation");
        refused.expect_err("authoritative commit must refuse the changed staged plan");

        let action_input = with_correlation("managed-action");
        let authority = InvocationGate::prepare_admitted_dev_input(
            InvocationSource::LocalAction,
            ServerProfile::Test,
            &action_input,
            snapback
                .admission
                .admit_dev()
                .expect("admit managed action fixture"),
        )
        .expect("prepare managed action authority");
        let function = snapback
            .function("emptyAction")
            .expect("managed action function")
            .clone();
        let prepared =
            InvocationGate::prepare_function(authority, &function).expect("prepare managed action");
        let action = snapback
            .stage_managed_host_plan_action(
                "emptyAction",
                action_input,
                super::manual_action_metadata("test", "emptyAction"),
                prepared,
            )
            .expect("stage managed action");
        let action_controller = snapback.admission.clone();
        BEFORE_ACTION_RESULT_HANDOFF_HOOK.with(|slot| {
            *slot.borrow_mut() = Some(Box::new(move || {
                assert_eq!(
                    action_controller
                        .retire_current_epoch_for_test()
                        .unwrap_err()
                        .diagnostic
                        .code,
                    "SNAPBACK_AUTH_MODE_QUIESCENCE_TIMEOUT"
                );
            }));
        });
        assert_eq!(
            action
                .finish(Ok(Value::Null))
                .expect_err("retired managed action result")
                .diagnostic
                .code,
            "SNAPBACK_AUTH_MODE_PENDING"
        );

        snapback
            .telemetry
            .force_flush()
            .expect("flush function observations");
        let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
            &database_path,
        ))
        .expect("open function telemetry sibling");
        for (name, correlation) in [("hostInsert", "host-staged"), ("ibexInsert", "ibex-staged")] {
            let count: i64 = raw
                .query_row(
                    "SELECT COUNT(*) FROM telemetry_events WHERE kind='function_run' AND name=?1 AND phase='joined' AND status=200 AND correlation=?2",
                    rusqlite::params![name, correlation],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(count, 1, "one completed function span for {name}");
        }
        let refused_terminal: (i64, String) = raw
            .query_row(
                "SELECT status,code FROM telemetry_events WHERE kind='function_run' AND name='hostInsert' AND phase='joined' AND correlation='host-refused' ORDER BY id DESC LIMIT 1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("authoritative refusal observation");
        assert_eq!(refused_terminal.0, 500);
        assert!(!refused_terminal.1.is_empty());
        let refused_successes: i64 = raw
            .query_row(
                "SELECT COUNT(*) FROM telemetry_events WHERE kind='function_run' AND name='hostInsert' AND phase='joined' AND status=200 AND correlation='host-refused'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            refused_successes, 0,
            "authoritative refusal cannot retain staging status=200"
        );
        let managed_failure: (i64, String) = raw
            .query_row(
                "SELECT status,code FROM telemetry_events WHERE kind='function_run' AND name='emptyAction' AND phase='joined' AND correlation='managed-action' ORDER BY id DESC LIMIT 1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("managed action handoff terminal");
        assert_eq!(
            (managed_failure.0, managed_failure.1.as_str()),
            (500, "SNAPBACK_AUTH_MODE_PENDING")
        );
        let logged: i64 = raw
            .query_row(
                "SELECT COUNT(*) FROM telemetry_events WHERE kind='log' AND name='log' AND correlation='ibex-staged' AND details LIKE '%staged-log%'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(logged, 1, "runtime.log stays bound to the staged handler");
    }

    #[test]
    fn telemetry_config_persist_failure_restores_the_previous_runtime_policy() {
        let directory = tempfile::tempdir().expect("config telemetry fixture directory");
        let database_path = directory.path().join("config-telemetry.sqlite3");
        let mut snapback = LocalSnapback::open(&database_path).expect("file-backed config fixture");
        snapback.telemetry.point(
            "lifecycle",
            "before_failed_config",
            Some(200),
            None,
            None,
            None,
            crate::telemetry::Priority::Normal,
        );
        snapback
            .telemetry
            .force_flush()
            .expect("establish telemetry before failed config transition");
        let telemetry_path = crate::telemetry::Telemetry::path_for_database(&database_path);
        let raw = rusqlite::Connection::open(&telemetry_path)
            .expect("open telemetry sibling before failed config transition");
        let floor_before: i64 = raw
            .query_row(
                "SELECT retention_floor FROM telemetry_meta WHERE singleton=1",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let visible_before: i64 = raw
            .query_row(
                "SELECT COUNT(*) FROM telemetry_events_visible WHERE name='before_failed_config'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(visible_before, 1);
        drop(raw);
        let config_path = crate::config::ConfigStore::path_for_database(&database_path);
        std::fs::create_dir(&config_path).expect("block atomic config rename with a directory");

        let disabled = crate::telemetry::TelemetryConfig {
            max_days: 0,
            ..crate::telemetry::TelemetryConfig::default()
        };
        let error = snapback
            .set_telemetry_config(disabled)
            .expect_err("config persistence must fail");
        assert_eq!(error.diagnostic.code, "SNAPBACK_CONFIG_STORE_IO");
        assert_eq!(
            snapback.config.telemetry_config(),
            &crate::telemetry::TelemetryConfig::default(),
            "failed persistence does not publish a new durable config"
        );

        let raw = rusqlite::Connection::open(&telemetry_path)
            .expect("reopen telemetry sibling after failed config transition");
        let floor_after: i64 = raw
            .query_row(
                "SELECT retention_floor FROM telemetry_meta WHERE singleton=1",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let visible_after: i64 = raw
            .query_row(
                "SELECT COUNT(*) FROM telemetry_events_visible WHERE name='before_failed_config'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            floor_after, floor_before,
            "failed persistence cannot advance the privacy floor"
        );
        assert_eq!(
            visible_after, 1,
            "failed persistence cannot hide an existing event"
        );
        drop(raw);

        snapback.telemetry.point(
            "lifecycle",
            "config_compensation_probe",
            Some(200),
            None,
            None,
            None,
            crate::telemetry::Priority::Normal,
        );
        snapback
            .telemetry
            .force_flush()
            .expect("the compensated runtime accepts observations");
        let raw =
            rusqlite::Connection::open(&telemetry_path).expect("open unchanged telemetry sibling");
        let count: i64 = raw
            .query_row(
                "SELECT COUNT(*) FROM telemetry_events WHERE kind='lifecycle' AND name='config_compensation_probe'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 1);
    }

    #[test]
    fn function_activation_publishes_exact_release_before_lifecycle_marker() {
        let mut snapback = LocalSnapback::memory().expect("release activation fixture");
        let release = "bundle-release".repeat(1_024);
        let diagnostics = snapback.load_functions(FunctionManifest {
            bundle_hash: Some(release.clone()),
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics.iter().all(|diagnostic| !matches!(
                diagnostic.severity,
                crate::diagnostic::DiagnosticSeverity::Error
                    | crate::diagnostic::DiagnosticSeverity::Fatal
            )),
            "activation diagnostics: {diagnostics:?}"
        );
        snapback
            .telemetry
            .force_flush()
            .expect("flush release lifecycle");
        assert_eq!(
            snapback
                .telemetry
                .event_releases_for_test("lifecycle", "process_start"),
            vec![None],
            "pre-activation lifecycle evidence has no release"
        );
        assert_eq!(
            snapback
                .telemetry
                .event_releases_for_test("lifecycle", "release_activation"),
            vec![Some(release.clone())],
            "activation marker is attributed to the exact installed bundle"
        );

        let pair_release = "pair-release".repeat(1_024);
        let generation = snapback
            .reserve_function_publication_generation()
            .expect("reserve complete-pair publication");
        let diagnostics = snapback.publish_preflighted_functions(
            FunctionManifest {
                bundle_hash: Some(pair_release.clone()),
                ..FunctionManifest::default()
            },
            generation,
            DiagnosticBoundary::Attached,
        );
        assert!(
            diagnostics.iter().all(|diagnostic| !matches!(
                diagnostic.severity,
                crate::diagnostic::DiagnosticSeverity::Error
                    | crate::diagnostic::DiagnosticSeverity::Fatal
            )),
            "complete-pair activation diagnostics: {diagnostics:?}"
        );
        snapback
            .telemetry
            .force_flush()
            .expect("flush complete-pair release lifecycle");
        assert_eq!(
            snapback
                .telemetry
                .event_releases_for_test("lifecycle", "release_activation"),
            vec![Some(release), Some(pair_release)],
            "both activation paths publish their exact bundle before the marker"
        );
    }

    #[test]
    fn target_descriptor_identity_survives_restart_and_compatibility_open_unbinds() {
        let directory = tempfile::tempdir().expect("target identity fixture directory");
        let database_path = directory.path().join("target-identity.sqlite3");
        let environment_id = "opaque-environment-identity";
        let target = target_descriptor(environment_id);
        let app_id = SchemaManifest::default().app_id;

        let snapback = LocalSnapback::open_for_target(&database_path, &target)
            .expect("open descriptor-bound instance");
        snapback
            .telemetry
            .force_flush()
            .expect("flush descriptor-bound process start");
        let telemetry_path = crate::telemetry::Telemetry::path_for_database(&database_path);
        let first: (String, Option<String>, Option<String>) =
            rusqlite::Connection::open(&telemetry_path)
                .unwrap()
                .query_row(
                    "SELECT generation,app_id,environment FROM telemetry_meta WHERE singleton=1",
                    [],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                )
                .unwrap();
        assert_eq!(first.1.as_deref(), Some(app_id.as_str()));
        assert_eq!(first.2.as_deref(), Some(environment_id));
        drop(snapback);

        let reopened = LocalSnapback::open_for_target(&database_path, &target)
            .expect("reopen under the same descriptor");
        reopened.telemetry.force_flush().unwrap();
        let same: (String, Option<String>, Option<String>) =
            rusqlite::Connection::open(&telemetry_path)
                .unwrap()
                .query_row(
                    "SELECT generation,app_id,environment FROM telemetry_meta WHERE singleton=1",
                    [],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                )
                .unwrap();
        assert_eq!(same, first, "same descriptor does not rotate identity");
        drop(reopened);

        let compatibility = LocalSnapback::open(&database_path)
            .expect("compatibility open remains available but unbound");
        compatibility.telemetry.force_flush().unwrap();
        let unbound: (String, Option<String>, Option<String>) =
            rusqlite::Connection::open(&telemetry_path)
                .unwrap()
                .query_row(
                    "SELECT generation,app_id,environment FROM telemetry_meta WHERE singleton=1",
                    [],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                )
                .unwrap();
        assert_ne!(unbound.0, first.0);
        assert_eq!((unbound.1, unbound.2), (None, None));
    }

    #[test]
    fn schema_app_identity_change_rotates_without_relabeling_predecessor_rows() {
        let directory = tempfile::tempdir().expect("schema identity fixture directory");
        let database_path = directory.path().join("schema-identity.sqlite3");
        let environment_id = "preview-exact";
        let target = target_descriptor(environment_id);
        let mut snapback = LocalSnapback::open_for_target(&database_path, &target)
            .expect("open descriptor-bound instance");
        snapback.telemetry.force_flush().unwrap();
        let telemetry_path = crate::telemetry::Telemetry::path_for_database(&database_path);
        let predecessor_generation: String = rusqlite::Connection::open(&telemetry_path)
            .unwrap()
            .query_row(
                "SELECT generation FROM telemetry_meta WHERE singleton=1",
                [],
                |row| row.get(0),
            )
            .unwrap();

        let same_app = SchemaManifest {
            generated_at: Some(1),
            ..SchemaManifest::default()
        };
        snapback
            .apply_schema(same_app)
            .expect("publish same-app schema");
        let same_generation: String = rusqlite::Connection::open(&telemetry_path)
            .unwrap()
            .query_row(
                "SELECT generation FROM telemetry_meta WHERE singleton=1",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(same_generation, predecessor_generation);

        let successor_app_id = "successor-app-identity".to_owned();
        let successor = SchemaManifest {
            app_id: successor_app_id.clone(),
            generated_at: Some(2),
            ..SchemaManifest::default()
        };
        let diagnostics = snapback
            .apply_schema(successor)
            .expect("publish successor app identity");
        assert!(diagnostics.iter().all(|diagnostic| !matches!(
            diagnostic.severity,
            crate::diagnostic::DiagnosticSeverity::Error
                | crate::diagnostic::DiagnosticSeverity::Fatal
        )));

        let raw = rusqlite::Connection::open(&telemetry_path).unwrap();
        let successor_meta: (String, String, String) = raw
            .query_row(
                "SELECT generation,app_id,environment FROM telemetry_meta WHERE singleton=1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_ne!(successor_meta.0, predecessor_generation);
        assert_eq!(successor_meta.1, successor_app_id);
        assert_eq!(successor_meta.2, environment_id);
        let total: i64 = raw
            .query_row("SELECT count(*) FROM telemetry_events", [], |row| {
                row.get(0)
            })
            .unwrap();
        let visible: i64 = raw
            .query_row("SELECT count(*) FROM telemetry_events_visible", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert!(total > 0, "predecessor rows remain physically present");
        assert_eq!(visible, 0, "predecessor rows are generation-hidden");
    }

    #[test]
    fn descriptor_bound_reset_rotates_generation_and_preserves_exact_identity() {
        let directory = tempfile::tempdir().expect("reset identity fixture directory");
        let database_path = directory.path().join("reset-identity.sqlite3");
        let environment_id = "reset-environment-from-descriptor";
        let target = target_descriptor(environment_id);
        let mut snapback = LocalSnapback::open_for_target(&database_path, &target)
            .expect("open descriptor-bound reset fixture");
        snapback.telemetry.force_flush().unwrap();
        let telemetry_path = crate::telemetry::Telemetry::path_for_database(&database_path);
        let before: (String, String, String) = rusqlite::Connection::open(&telemetry_path)
            .unwrap()
            .query_row(
                "SELECT generation,app_id,environment FROM telemetry_meta WHERE singleton=1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();

        snapback.reset().expect("descriptor-bound reset commits");
        snapback
            .telemetry
            .force_flush()
            .expect("flush successor reset lifecycle");
        let after: (String, String, String) = rusqlite::Connection::open(&telemetry_path)
            .unwrap()
            .query_row(
                "SELECT generation,app_id,environment FROM telemetry_meta WHERE singleton=1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_ne!(after.0, before.0);
        assert_eq!(after.1, before.1);
        assert_eq!(after.2, before.2);
        assert_eq!(after.1, SchemaManifest::default().app_id);
        assert_eq!(after.2, environment_id);
    }

    #[test]
    fn telemetry_runtime_config_failure_compensates_the_durable_config() {
        let directory = tempfile::tempdir().expect("runtime config failure fixture directory");
        let database_path = directory.path().join("runtime-config-failure.sqlite3");
        let mut snapback = LocalSnapback::open(&database_path).expect("file-backed config fixture");
        let previous = crate::telemetry::TelemetryConfig::default();
        let mut replacement = previous.clone();
        replacement.max_days = previous.max_days.saturating_sub(1);

        snapback.telemetry.point(
            "lifecycle",
            "before_runtime_config_failure",
            Some(200),
            None,
            None,
            None,
            crate::telemetry::Priority::Normal,
        );
        snapback
            .telemetry
            .force_flush()
            .expect("establish telemetry sibling before injected runtime failure");
        snapback.telemetry.fail_next_config_update_for_test();
        let error = snapback
            .set_telemetry_config(replacement)
            .expect_err("injected runtime transition must fail");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_TELEMETRY_TEST_CONFIG_FAILED"
        );
        assert_eq!(snapback.config.telemetry_config(), &previous);
        let reopened = crate::config::ConfigStore::open(
            crate::config::ConfigStore::path_for_database(&database_path),
        )
        .expect("reopen compensated durable config");
        assert_eq!(reopened.telemetry_config(), &previous);

        snapback.telemetry.point(
            "lifecycle",
            "runtime_config_compensation_probe",
            Some(200),
            None,
            None,
            None,
            crate::telemetry::Priority::Normal,
        );
        snapback
            .telemetry
            .force_flush()
            .expect("prior runtime policy remains live after failed transition");
        let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
            &database_path,
        ))
        .expect("open runtime compensation telemetry sibling");
        let count: i64 = raw
            .query_row(
                "SELECT COUNT(*) FROM telemetry_events_visible WHERE name='runtime_config_compensation_probe'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 1);
    }

